class CapituloExtra {
  final String titulo;
  final String objetivo;
  final String explicacion;
  final List<List<String>> vocab;
  final List<String> ejemplos;
  final List<List<String>> preguntas;
  const CapituloExtra(this.titulo, this.objetivo, this.explicacion, this.vocab, this.ejemplos, this.preguntas);
}

class UnidadExtra {
  final int n;
  final String nombre;
  final bool premium;
  final List<CapituloExtra> capitulos;
  const UnidadExtra(this.n, this.nombre, this.premium, this.capitulos);
}

class UnidadesExtra {
  static UnidadExtra? m_porId(String id) {
    for (final u in todas) {
      if ('unidad${u.n}' == id) return u;
    }
    return null;
  }

  static CapituloExtra? m_capitulo(String unidadId, int indice) {
    final u = m_porId(unidadId);
    if (u == null || indice < 0 || indice >= u.capitulos.length) return null;
    return u.capitulos[indice];
  }

