        [['lettuce', 'lechuga'], ['tomato', 'jitomate'], ['onion', 'cebolla'], ['carrot', 'zanahoria'], ['potato', 'papa'], ['cucumber', 'pepino'], ['spinach', 'espinaca'], ['broccoli', 'brócoli']],
        ['I need three tomatoes and two onions. — Necesito tres jitomates y dos cebollas.', 'Do we have any carrots at home? — ¿Tenemos zanahorias en casa?'],
        [['I am buying two ___.', 'potatoes', 'potatos', 'potatoe', 'a potato', 'El plural de “potato” es “potatoes”.'], ['I want to make a salad. I need ___.', 'lettuce', 'flour', 'butter', 'rice', 'Una ensalada lleva lechuga: “lettuce”.']]),
      CapituloExtra('Carnes, lácteos y despensa', 'Aprender a nombrar alimentos básicos de la despensa.', 'Muchos alimentos son incontables y no llevan plural ni “a”: “milk”, “rice”, “cheese”. Usa “some” en afirmativas: “I need some milk”. En preguntas y negativas usa “any”: “Do we have any rice?”.',
        [['chicken', 'pollo'], ['beef', 'carne de res'], ['cheese', 'queso'], ['milk', 'leche'], ['butter', 'mantequilla'], ['rice', 'arroz'], ['flour', 'harina'], ['eggs', 'huevos']],
        ['I need some milk and cheese. — Necesito leche y queso.', 'Do we have any rice? — ¿Tenemos arroz?'],
        [['Do we have ___ butter?', 'any', 'a', 'many', 'an', 'En preguntas con incontables se usa “any”.'], ['I need ___ cheese for the pizza.', 'some', 'a', 'many', 'two cheeses of', '“Cheese” es incontable; en afirmativas se usa “some”.']]),
      CapituloExtra('Envases y empaques', 'Aprender a pedir productos por envase usando of.', 'Para contar productos incontables usamos envases seguidos de “of”: “a bottle of water”, “a box of cereal”. En plural, el envase cambia: “two bottles of water”. Ejemplo: “I want a jar of honey”.',
        [['bottle', 'botella'], ['can', 'lata'], ['box', 'caja'], ['bag', 'bolsa'], ['jar', 'frasco'], ['pack', 'paquete'], ['dozen', 'docena'], ['kilo', 'kilo']],
        ['I need two bottles of water. — Necesito dos botellas de agua.', 'Please give me a dozen eggs. — Por favor, deme una docena de huevos.'],
        [['I would like a ___ of cereal.', 'box', 'dozen', 'kilo', 'slice', 'El cereal se vende en caja: “a box of cereal”.'], ['We need two ___ of soup.', 'cans', 'can', 'cans of the', 'a can', 'Con “two” el envase va en plural: “cans”.']]),
      CapituloExtra('Cuánto y cuántos', 'Aprender a preguntar cantidades con much y many.', 'Usa “How much” con sustantivos incontables: “How much milk do we need?”. Usa “How many” con contables en plural: “How many eggs do we need?”. También hay porciones como “a loaf of bread” o “a slice of cheese”.',
        [['bunch', 'manojo'], ['slice', 'rebanada'], ['loaf', 'barra de pan'], ['carton', 'caja de cartón'], ['liter', 'litro'], ['pound', 'libra'], ['piece', 'pieza'], ['gram', 'gramo']],
        ['How much milk do we need? — ¿Cuánta leche necesitamos?', 'I want a loaf of bread and a bunch of bananas. — Quiero una barra de pan y un racimo de plátanos.'],
        [['How ___ eggs do we need?', 'many', 'much', 'a lot', 'any', '“Eggs” es contable plural, se usa “How many”.'], ['How ___ juice is there?', 'much', 'many', 'few', 'some', '“Juice” es incontable, se usa “How much”.']]),
      CapituloExtra('Pagar y ahorrar', 'Aprender a pagar en caja y a ahorrar con cupones.', 'En la caja puedes escuchar “Cash or card?” y responder “Card, please”. Para pedir el recibo di “Can I have the receipt?”. Para ahorrar busca descuentos y cupones: “I have a coupon”.',
        [['list', 'lista'], ['receipt', 'recibo'], ['coupon', 'cupón'], ['discount', 'descuento'], ['change', 'cambio'], ['cash', 'efectivo'], ['label', 'etiqueta'], ['ingredient', 'ingrediente']],
        ['Can I have the receipt, please? — ¿Me da el recibo, por favor?', 'I have a coupon for this cereal. — Tengo un cupón para este cereal.'],
        [['I paid with a twenty and the cashier gave me my ___.', 'change', 'coupon', 'label', 'ingredient', 'El dinero que te devuelven es el “change” (cambio).'], ['Can I have the ___, please? I want to check the prices.', 'receipt', 'cash', 'discount', 'list of', 'El comprobante de compra es el “receipt”.']]),
    ]),
    UnidadExtra(26, 'Adjetivos y comparaciones', false, [
      CapituloExtra('Adjetivos básicos', 'Aprender a describir personas y cosas con adjetivos comunes.', 'Los adjetivos describen sustantivos y no cambian por género ni número: “a big house”, “two big houses”. Van después de be o antes del sustantivo.',
        [['big', 'grande'], ['small', 'pequeño'], ['tall', 'alto'], ['short', 'bajo, corto'], ['new', 'nuevo'], ['old', 'viejo'], ['cheap', 'barato'], ['expensive', 'caro']],
        ['My house is big. — Mi casa es grande.', 'These shoes are cheap. — Estos zapatos son baratos.'],
        [['The elephant is very ___.', 'big', 'bigs', 'bigly', 'a big', 'El adjetivo va después de be y no lleva -s: big.'], ['Which word is the opposite of “cheap”?', 'expensive', 'small', 'short', 'new', 'Lo contrario de barato (cheap) es caro (expensive).']]),
      CapituloExtra('Posición del adjetivo', 'Aprender a colocar los adjetivos antes del sustantivo.', 'En inglés el adjetivo va antes del sustantivo, al revés que en español: “a red car”, no “a car red”. Tampoco concuerda en plural: “two beautiful girls”.',
        [['beautiful', 'hermoso'], ['ugly', 'feo'], ['clean', 'limpio'], ['dirty', 'sucio'], ['heavy', 'pesado'], ['light', 'ligero'], ['quiet', 'tranquilo, callado'], ['noisy', 'ruidoso']],
        ['She has a beautiful dress. — Ella tiene un vestido hermoso.', 'It is a quiet street. — Es una calle tranquila.'],
        [['I have a ___ car.', 'clean white', 'car clean', 'cleans white', 'white cleans', 'El adjetivo va antes del sustantivo y no lleva -s.'], ['Which is the correct sentence?', 'They are noisy children.', 'They are children noisy.', 'They are noisies children.', 'They are children noisies.', 'Adjetivo antes del sustantivo y sin plural.']]),
      CapituloExtra('Comparativos cortos', 'Aprender a comparar con adjetivos cortos usando -er than.', 'Con adjetivos de una sílaba agrega -er y usa “than”: “Tom is taller than Ana”. Si termina en consonante, a veces se duplica: “big – bigger”.',
        [['taller', 'más alto'], ['faster', 'más rápido'], ['slower', 'más lento'], ['younger', 'más joven'], ['longer', 'más largo'], ['warmer', 'más cálido'], ['colder', 'más frío'], ['harder', 'más duro, más difícil']],
        ['My brother is taller than me. — Mi hermano es más alto que yo.', 'Today is colder than yesterday. — Hoy hace más frío que ayer.'],
        [['A car is ___ a bicycle.', 'faster than', 'more fast than', 'fast than', 'fastest than', 'Adjetivo corto: faster + than.'], ['The comparative of “big” is ___.', 'bigger', 'biger', 'more big', 'bigest', 'Se duplica la g y se agrega -er: bigger.']]),
      CapituloExtra('Comparativos largos', 'Aprender a comparar con more, less y formas irregulares.', 'Con adjetivos largos usa “more … than”: “This book is more interesting than that one”. “Good” y “bad” son irregulares: better y worse.',
        [['more interesting', 'más interesante'], ['more difficult', 'más difícil'], ['more comfortable', 'más cómodo'], ['more dangerous', 'más peligroso'], ['more popular', 'más popular'], ['better', 'mejor'], ['worse', 'peor'], ['less', 'menos']],
        ['English is more difficult than Spanish for me. — El inglés es más difícil que el español para mí.', 'This sofa is better than that chair. — Este sofá es mejor que esa silla.'],
        [['This movie is ___ than the book.', 'more interesting', 'interestinger', 'most interesting', 'more interested', 'Adjetivo largo: more + adjetivo + than.'], ['My cold today is ___ than yesterday.', 'worse', 'badder', 'more bad', 'worst', 'El comparativo irregular de bad es worse.']]),
      CapituloExtra('Superlativos', 'Aprender a decir quién o qué es el más… de un grupo.', 'Para el superlativo usa “the” + -est (adjetivos cortos) o “the most” (largos): “the tallest”, “the most beautiful”. Irregulares: the best, the worst.',
        [['the tallest', 'el más alto'], ['the biggest', 'el más grande'], ['the most beautiful', 'el más hermoso'], ['the best', 'el mejor'], ['the worst', 'el peor'], ['the most expensive', 'el más caro'], ['the cheapest', 'el más barato'], ['the oldest', 'el más viejo']],
        ['She is the tallest girl in the class. — Ella es la niña más alta de la clase.', 'This is the best pizza in town. — Esta es la mejor pizza de la ciudad.'],
        [['Mount Everest is ___ mountain in the world.', 'the highest', 'higher', 'the most high', 'highest than', 'Superlativo corto: the + highest.'], ['That is ___ hotel in the city.', 'the most expensive', 'the expensivest', 'more expensive', 'the more expensive', 'Adjetivo largo: the most + adjetivo.']]),
      CapituloExtra('Igualdad y diferencia', 'Aprender a decir que dos cosas son iguales o distintas y practicar todo.', 'Para igualdad usa “as + adjetivo + as”: “Ana is as tall as Luis”. Para negar, “not as … as”. También: “the same as”, “different from” y “similar to”.',
        [['as...as', 'tan... como'], ['not as...as', 'no tan... como'], ['the same as', 'igual que'], ['different from', 'diferente de'], ['similar to', 'parecido a'], ['much', 'mucho (más)'], ['a little', 'un poco'], ['than', 'que (comparación)']],
        ['My phone is as old as yours. — Mi teléfono es tan viejo como el tuyo.', 'Her bag is different from mine. — Su bolsa es diferente de la mía.'],
        [['This bag is ___ expensive as that one.', 'as', 'than', 'more', 'most', 'La estructura es as + adjetivo + as.'], ['Pedro and Juan are twins. Pedro is ___ Juan.', 'the same age as', 'older as', 'more age than', 'same as age', '“The same age as” expresa igualdad de edad.']]),
    ]),
    UnidadExtra(27, 'Preguntas y respuestas', false, [
      CapituloExtra('Palabras interrogativas', 'Aprender las palabras básicas para preguntar información.', 'Las palabras interrogativas van al inicio de la pregunta: “What is your name?”, “Where do you live?”. Cada una pide un dato distinto: lugar, tiempo, persona, razón.',
        [['what', 'qué, cuál'], ['where', 'dónde'], ['when', 'cuándo'], ['who', 'quién'], ['why', 'por qué'], ['how', 'cómo'], ['which', 'cuál (entre opciones)'], ['whose', 'de quién']],
        ['Where do you work? — ¿Dónde trabajas?', 'Who is that man? — ¿Quién es ese hombre?'],
        [['___ is your birthday? It is in May.', 'When', 'Where', 'Who', 'Why', 'Se pregunta por el tiempo: when.'], ['___ do you live? I live in Puebla.', 'Where', 'When', 'Whose', 'Why', 'Se pregunta por el lugar: where.']]),
      CapituloExtra('Preguntas con to be', 'Aprender a preguntar con am, is, are, was y were.', 'Con to be se invierte el orden: “You are tired” se vuelve “Are you tired?”. No se usa do/does con be. En pasado usa was/were: “Were you at home?”.',
        [['am', 'soy, estoy'], ['is', 'es, está'], ['are', 'eres, son, estás'], ['was', 'fui, era, estuve'], ['were', 'fuiste, eran, estuvimos'], ['isn\'t', 'no es, no está'], ['aren\'t', 'no eres, no son'], ['wasn\'t', 'no fue, no estaba']],
        ['Are you a student? — ¿Eres estudiante?', 'Was she at the party? — ¿Estuvo ella en la fiesta?'],
        [['___ your parents at home?', 'Are', 'Is', 'Do', 'Does', 'Parents es plural y la pregunta usa be: Are.'], ['___ he a doctor?', 'Is', 'Does', 'Are', 'Do', 'Con he se usa is, y con be no se usa do.']]),
      CapituloExtra('Preguntas con do y does', 'Aprender a preguntar en presente simple con do y does.', 'En presente simple usa “Do” con I, you, we, they y “Does” con he, she, it. El verbo principal queda sin -s: “Does she work here?”. Para negar: don\'t / doesn\'t.',
        [['do', 'auxiliar (I, you, we, they)'], ['does', 'auxiliar (he, she, it)'], ['don\'t', 'no (I, you, we, they)'], ['doesn\'t', 'no (he, she, it)'], ['always', 'siempre'], ['usually', 'normalmente'], ['sometimes', 'a veces'], ['often', 'a menudo']],
        ['Do you speak English? — ¿Hablas inglés?', 'Does he play soccer on Sundays? — ¿Juega él futbol los domingos?'],
        [['___ your sister like coffee?', 'Does', 'Do', 'Is', 'Are', 'Con sister (she) se usa does.'], ['Does Ana ___ in a bank?', 'work', 'works', 'working', 'worked', 'Después de does el verbo va en forma base: work.']]),
      CapituloExtra('Preguntas en pasado con did', 'Aprender a preguntar sobre acciones terminadas en el pasado.', 'En pasado simple usa “Did” con todos los sujetos y el verbo en forma base: “Did you call her?”. La respuesta negativa usa “didn\'t”: “I didn\'t call”.',
        [['did', 'auxiliar de pasado'], ['didn\'t', 'no (pasado)'], ['yesterday', 'ayer'], ['last night', 'anoche'], ['ago', 'hace (tiempo)'], ['last week', 'la semana pasada'], ['last year', 'el año pasado'], ['then', 'entonces']],
        ['Did you watch the game last night? — ¿Viste el partido anoche?', 'Did they arrive two hours ago? — ¿Llegaron hace dos horas?'],
        [['Did you ___ the movie yesterday?', 'see', 'saw', 'seen', 'sees', 'Después de did el verbo va en forma base: see.'], ['___ she call you last night?', 'Did', 'Does', 'Do', 'Was', 'El tiempo es pasado (last night), así que se usa did.']]),
      CapituloExtra('Respuestas cortas', 'Aprender a responder preguntas de sí o no de forma natural.', 'Responde repitiendo el auxiliar de la pregunta: “Do you like tea?” – “Yes, I do.” / “No, I don\'t.”. Con be: “Are you tired?” – “Yes, I am.”. No uses la forma corta de am en afirmativo.',
        [['yes, I am', 'sí, lo soy'], ['no, he isn\'t', 'no, él no lo es'], ['yes, they do', 'sí, ellos sí'], ['no, she doesn\'t', 'no, ella no'], ['yes, we did', 'sí, nosotros sí (pasado)'], ['no, I didn\'t', 'no, yo no (pasado)'], ['of course', 'claro que sí'], ['not really', 'la verdad que no']],
        ['Do you live here? — Yes, I do. — ¿Vives aquí? — Sí.', 'Is he your brother? — No, he isn\'t. — ¿Es tu hermano? — No.'],
        [['Does she speak French? — Yes, she ___.', 'does', 'is', 'do', 'speaks', 'Se responde con el mismo auxiliar: does.'], ['Are they your friends? — No, they ___.', 'aren\'t', 'don\'t', 'doesn\'t', 'isn\'t', 'La pregunta usa are, así que la respuesta es aren\'t.']]),
      CapituloExtra('Cantidad y detalles', 'Aprender a preguntar cantidad, duración, frecuencia y edad.', 'Combina how con otras palabras: “How much” (incontables y precios), “How many” (contables), “How long”, “How often”, “How old”, “How far”. Ejemplo: “How many brothers do you have?”.',
        [['how much', 'cuánto (incontable)'], ['how many', 'cuántos (contable)'], ['how long', 'cuánto tiempo, qué tan largo'], ['how often', 'con qué frecuencia'], ['how old', 'qué edad'], ['how far', 'qué tan lejos'], ['what time', 'a qué hora'], ['what kind', 'qué tipo']],
        ['How much is this shirt? — ¿Cuánto cuesta esta camisa?', 'How often do you exercise? — ¿Con qué frecuencia haces ejercicio?'],
        [['___ brothers do you have?', 'How many', 'How much', 'How far', 'How old', 'Brothers es contable: how many.'], ['___ is the airport? It is ten kilometers away.', 'How far', 'How often', 'How many', 'What time', 'Se pregunta por la distancia: how far.']]),
    ]),
    UnidadExtra(28, 'Verbos modales', false, [
      CapituloExtra('Can: habilidad y permiso', 'Aprender a hablar de habilidades y permisos con can.', '“Can” va seguido del verbo en forma base, sin to y sin -s: “She can swim”. Se niega con can\'t o cannot y se pregunta invirtiendo: “Can you help me?”.',
        [['can', 'poder, saber'], ['can\'t', 'no poder'], ['cannot', 'no poder (forma completa)'], ['be able to', 'ser capaz de'], ['swim', 'nadar'], ['drive', 'manejar'], ['speak', 'hablar'], ['sing', 'cantar']],
        ['I can swim very well. — Sé nadar muy bien.', 'He can\'t drive yet. — Él todavía no puede manejar.'],
        [['She can ___ three languages.', 'speak', 'speaks', 'to speak', 'speaking', 'Después de can va el verbo base: speak.'], ['___ you help me, please?', 'Can', 'Do', 'Are', 'Does', 'Para pedir ayuda se usa Can you…?']]),
      CapituloExtra('Could: pasado y cortesía', 'Aprender a usar could para el pasado y las peticiones corteses.', '“Could” es el pasado de can para habilidades: “I could run fast when I was young”. También hace una petición más amable: “Could you open the door?”.',
        [['could', 'podía, podría'], ['couldn\'t', 'no podía'], ['was able to', 'pude (una vez)'], ['polite request', 'petición cortés'], ['as a child', 'de niño'], ['could you', '¿podrías?'], ['could I', '¿podría yo?'], ['maybe', 'quizás']],
        ['When I was six, I could ride a bike. — Cuando tenía seis años, sabía andar en bicicleta.', 'Could you repeat that, please? — ¿Podrías repetir eso, por favor?'],
        [['When I was a child, I ___ climb trees.', 'could', 'can', 'am able', 'will can', 'Habilidad en el pasado: could.'], ['Which sentence is more polite?', 'Could you close the window?', 'Close the window.', 'You close the window.', 'Can close window?', 'Could you…? es la petición más cortés.']]),
      CapituloExtra('Should: consejos', 'Aprender a dar consejos con should y shouldn\'t.', '“Should” sirve para dar consejos y va con el verbo base: “You should rest”. Lo contrario es “shouldn\'t”: “You shouldn\'t eat so much sugar”.',
        [['should', 'debería'], ['shouldn\'t', 'no debería'], ['ought to', 'debería (formal)'], ['had better', 'más vale que'], ['advice', 'consejo'], ['suggest', 'sugerir'], ['why don\'t you', '¿por qué no…?'], ['if I were you', 'yo en tu lugar']],
        ['You should drink more water. — Deberías tomar más agua.', 'He shouldn\'t stay up so late. — No debería quedarse despierto tan tarde.'],
        [['You have a headache. You ___ rest.', 'should', 'should to', 'shoulds', 'shouldn\'t to', 'Should va con verbo base y sin to.'], ['She ___ eat so much candy. It\'s bad for her teeth.', 'shouldn\'t', 'should', 'can', 'ought', 'Es un consejo negativo: shouldn\'t.']]),
      CapituloExtra('Must y have to', 'Aprender a expresar obligación y prohibición.', '“Must” y “have to” expresan obligación: “I must go”, “She has to work”. Ojo: “mustn\'t” es prohibido, pero “don\'t have to” significa que no es necesario.',
        [['must', 'deber, tener que'], ['mustn\'t', 'tener prohibido'], ['have to', 'tener que'], ['has to', 'tiene que'], ['don\'t have to', 'no es necesario'], ['doesn\'t have to', 'no necesita'], ['necessary', 'necesario'], ['forbidden', 'prohibido']],
        ['You must wear a seat belt. — Debes usar el cinturón de seguridad.', 'I don\'t have to work on Sunday. — No tengo que trabajar el domingo.'],
        [['Smoking is not allowed here. You ___ smoke.', 'mustn\'t', 'don\'t have to', 'should', 'can', 'Mustn\'t expresa una prohibición.'], ['Tomorrow is a holiday. We ___ go to school.', 'don\'t have to', 'mustn\'t', 'must', 'has to', 'Don\'t have to indica que no es necesario.']]),
      CapituloExtra('May y might: posibilidad', 'Aprender a hablar de posibilidades y pedir permiso con may.', '“May” y “might” expresan posibilidad: “It might rain today”. “May I…?” pide permiso de forma formal. Después van con verbo base, sin to.',
        [['may', 'puede que, ¿me permite?'], ['might', 'podría ser que'], ['may I', '¿me permite?'], ['might not', 'puede que no'], ['perhaps', 'quizás'], ['possibly', 'posiblemente'], ['probably', 'probablemente'], ['it\'s possible', 'es posible']],
        ['It might rain this afternoon. — Puede que llueva esta tarde.', 'May I come in? — ¿Puedo pasar?'],
        [['I\'m not sure. She ___ be at home.', 'might', 'must to', 'mights', 'does', 'Might expresa posibilidad y va con verbo base.'], ['___ I sit here, please?', 'May', 'Will', 'Must', 'Do', 'May I…? es la forma formal de pedir permiso.']]),
      CapituloExtra('Would: deseos y ofertas', 'Aprender a ofrecer, pedir y expresar preferencias con would.', '“Would like” es una forma amable de decir quiero: “I\'d like a coffee”. Para ofrecer algo: “Would you like some tea?”. “Would rather” expresa preferencia: “I\'d rather stay home”.',
        [['would', 'condicional, cortesía'], ['wouldn\'t', 'no haría'], ['would like', 'quisiera'], ['would you like', '¿te gustaría?'], ['I\'d like', 'quisiera'], ['would rather', 'preferiría'], ['would you mind', '¿te importaría?'], ['if', 'si']],
        ['Would you like some water? — ¿Te gustaría un poco de agua?', 'I\'d rather stay home tonight. — Preferiría quedarme en casa esta noche.'],
        [['I ___ like a glass of juice, please.', 'would', 'am', 'does', 'can to', 'I would like es la forma cortés de pedir algo.'], ['Would you ___ some cake?', 'like', 'likes', 'to like', 'liking', 'Después de would va el verbo base: like.']]),
    ]),
    UnidadExtra(29, 'Presente perfecto', false, [
      CapituloExtra('Cómo se forma', 'Aprender a formar el presente perfecto con have o has.', 'Se forma con have/has + participio pasado: “I have finished”, “She has called”. Con he, she, it usa has. Negativo: haven\'t / hasn\'t. Pregunta: “Have you eaten?”.',
        [['have', 'he, hemos, han'], ['has', 'ha (he, she, it)'], ['haven\'t', 'no he, no hemos'], ['hasn\'t', 'no ha'], ['participio', 'forma verbal pasada'], ['I\'ve', 'I have'], ['she\'s', 'she has'], ['been', 'sido, estado']],
        ['I have finished my homework. — He terminado mi tarea.', 'She has lived here for years. — Ella ha vivido aquí por años.'],
        [['He ___ finished his work.', 'has', 'have', 'is', 'did', 'Con he se usa has + participio.'], ['They ___ visited Mexico City.', 'have', 'has', 'does', 'are', 'Con they se usa have + participio.']]),
      CapituloExtra('Participios irregulares', 'Aprender los participios irregulares más comunes.', 'Muchos verbos tienen participio irregular que hay que memorizar: go – gone, see – seen, do – done. Los regulares terminan en -ed: “I have worked”.',
        [['gone', 'ido (go)'], ['seen', 'visto (see)'], ['done', 'hecho (do)'], ['eaten', 'comido (eat)'], ['written', 'escrito (write)'], ['taken', 'tomado (take)'], ['made', 'hecho (make)'], ['known', 'sabido, conocido (know)']],
        ['I have seen that movie. — He visto esa película.', 'She has written three books. — Ella ha escrito tres libros.'],
        [['I have ___ my breakfast.', 'eaten', 'ate', 'eat', 'eating', 'El participio de eat es eaten.'], ['We have ___ that actor before.', 'seen', 'saw', 'see', 'sees', 'El participio de see es seen.']]),
      CapituloExtra('Ever y never', 'Aprender a hablar de experiencias de vida con ever y never.', 'Usa “ever” en preguntas sobre experiencias: “Have you ever been to Canada?”. Usa “never” para decir que no ha pasado nunca: “I have never tried sushi”. Never ya es negativo.',
        [['ever', 'alguna vez'], ['never', 'nunca'], ['in my life', 'en mi vida'], ['once', 'una vez'], ['twice', 'dos veces'], ['three times', 'tres veces'], ['before', 'antes'], ['so far', 'hasta ahora']],
        ['Have you ever eaten tacos in Texas? — ¿Alguna vez has comido tacos en Texas?', 'I have never seen snow. — Nunca he visto nieve.'],
        [['Have you ___ been to Spain?', 'ever', 'never', 'yet', 'since', 'En preguntas de experiencia se usa ever.'], ['I have ___ flown in a plane. I\'m afraid of it.', 'never', 'ever', 'already', 'just', 'Dice que nunca lo ha hecho: never.']]),
      CapituloExtra('Already, yet y still', 'Aprender a hablar de lo que ya se hizo y lo que falta.', '“Already” va en afirmativas: “I have already eaten”. “Yet” va al final de negativas y preguntas: “I haven\'t called her yet”, “Have you finished yet?”.',
        [['already', 'ya'], ['yet', 'todavía, aún'], ['still', 'todavía (sigue)'], ['not yet', 'todavía no'], ['recently', 'recientemente'], ['lately', 'últimamente'], ['so', 'así que'], ['finally', 'por fin']],
        ['She has already left. — Ella ya se fue.', 'I haven\'t done my homework yet. — Todavía no hago mi tarea.'],
        [['I have ___ seen that movie. I saw it last week.', 'already', 'yet', 'ever', 'since', 'Already se usa en afirmativas para decir ya.'], ['Have you finished your project ___?', 'yet', 'already', 'ago', 'never', 'En preguntas se usa yet al final.']]),
      CapituloExtra('For y since', 'Aprender a decir desde cuándo o por cuánto tiempo.', 'Usa “for” con una duración: “for two years”. Usa “since” con un punto de inicio: “since 2020”, “since Monday”. Ambos responden a “How long…?”.',
        [['for', 'durante, por'], ['since', 'desde'], ['how long', 'cuánto tiempo'], ['all day', 'todo el día'], ['since Monday', 'desde el lunes'], ['for a week', 'por una semana'], ['for years', 'por años'], ['since then', 'desde entonces']],
        ['I have lived here for five years. — He vivido aquí por cinco años.', 'He has worked here since 2019. — Él trabaja aquí desde 2019.'],
        [['We have been friends ___ 2015.', 'since', 'for', 'ago', 'during', '2015 es un punto de inicio: since.'], ['She has studied English ___ three months.', 'for', 'since', 'from', 'ago', 'Three months es una duración: for.']]),
      CapituloExtra('Just y práctica', 'Aprender a hablar de acciones recientes y repasar la unidad.', '“Just” indica algo que acaba de pasar: “I have just arrived”. Cuidado: “has been to” significa que fue y volvió, y “has gone to” que sigue allá: “She has gone to Paris”.',
        [['just', 'acabar de'], ['just now', 'hace un momento'], ['a moment ago', 'hace un momento'], ['been to', 'haber ido y vuelto'], ['gone to', 'haberse ido a'], ['today', 'hoy'], ['this week', 'esta semana'], ['this morning', 'esta mañana']],
        ['They have just finished dinner. — Acaban de terminar la cena.', 'I have been to London twice. — He ido a Londres dos veces.'],
        [['I\'m sorry, Tom isn\'t here. He has ___ left.', 'just', 'ever', 'since', 'ago', 'Just indica que acaba de ocurrir.'], ['She is in Paris right now. She has ___ to Paris.', 'gone', 'been', 'went', 'going', 'Has gone to indica que sigue allá.']]),
    ]),
    UnidadExtra(30, 'Mi ciudad y mi comunidad', false, [
      CapituloExtra('Lugares de la ciudad', 'Aprender los nombres de lugares importantes de la ciudad.', 'Usa “There is” para uno y “There are” para varios: “There is a bank on the corner”, “There are two parks”. Para decir a dónde vas usa “go to the…”.',
        [['bank', 'banco'], ['post office', 'oficina de correos'], ['library', 'biblioteca'], ['hospital', 'hospital'], ['supermarket', 'supermercado'], ['park', 'parque'], ['pharmacy', 'farmacia'], ['school', 'escuela']],
        ['There is a library near my house. — Hay una biblioteca cerca de mi casa.', 'I go to the pharmacy every week. — Voy a la farmacia cada semana.'],
        [['I need medicine. I\'m going to the ___.', 'pharmacy', 'library', 'bank', 'school', 'Las medicinas se compran en la farmacia (pharmacy).'], ['There ___ two hospitals in my city.', 'are', 'is', 'be', 'does', 'Two es plural: there are.']]),
      CapituloExtra('Dar direcciones', 'Aprender a pedir y dar indicaciones para llegar a un lugar.', 'Para pedir: “Excuse me, how do I get to the bank?”. Para indicar usa imperativos: “Turn left”, “Go straight”. Con lugares: “next to”, “between”, “across from”.',
        [['turn left', 'da vuelta a la izquierda'], ['turn right', 'da vuelta a la derecha'], ['go straight', 'sigue derecho'], ['next to', 'junto a'], ['across from', 'enfrente de'], ['between', 'entre'], ['corner', 'esquina'], ['traffic light', 'semáforo']],
        ['Go straight and turn left at the corner. — Sigue derecho y da vuelta a la izquierda en la esquina.', 'The bank is next to the pharmacy. — El banco está junto a la farmacia.'],
        [['The school is ___ the park and the library.', 'between', 'next', 'across', 'on', 'Between se usa para algo situado entre dos lugares.'], ['Which means “da vuelta a la derecha”?', 'Turn right.', 'Turn left.', 'Go straight.', 'Stop here.', 'Turn right significa da vuelta a la derecha.']]),
      CapituloExtra('Transporte', 'Aprender a hablar del transporte público en la ciudad.', 'Con transporte público usa “by”: “by bus”, “by taxi”. Excepción: “on foot”. Para preguntar el tiempo: “How long does it take?”. Ejemplo: “I go to work by subway”.',
        [['bus stop', 'parada de autobús'], ['subway', 'metro'], ['taxi', 'taxi'], ['bike lane', 'ciclovía'], ['train station', 'estación de tren'], ['ticket', 'boleto'], ['route', 'ruta'], ['traffic', 'tráfico']],
        ['I go to work by subway. — Voy al trabajo en metro.', 'The bus stop is near the station. — La parada de autobús está cerca de la estación.'],
        [['She goes to school ___ bus.', 'by', 'in the', 'with', 'at', 'Con medios de transporte se usa by: by bus.'], ['You need a ___ to ride the train.', 'ticket', 'route', 'lane', 'corner', 'Para subir al tren necesitas un boleto (ticket).']]),
      CapituloExtra('Mi vecindario', 'Aprender a describir tu colonia y a la gente que vive en ella.', 'Para describir tu zona usa there is/there are y adjetivos: “My neighborhood is quiet”. Para hablar de relaciones: “my neighbor”, “our building”.',
        [['neighbor', 'vecino'], ['neighborhood', 'vecindario, colonia'], ['street', 'calle'], ['building', 'edificio'], ['apartment', 'departamento'], ['market', 'mercado'], ['plaza', 'plaza'], ['bakery', 'panadería']],
        ['My neighbor is very friendly. — Mi vecino es muy amable.', 'There is a bakery on my street. — Hay una panadería en mi calle.'],
        [['I live in an ___ on the third floor.', 'apartment', 'bakery', 'market', 'street', 'Se vive en un departamento (apartment); an va antes de vocal.'], ['The person who lives next door is my ___.', 'neighbor', 'building', 'plaza', 'ticket', 'La persona que vive al lado es tu vecino (neighbor).']]),
      CapituloExtra('Vida en comunidad', 'Aprender a hablar de actividades y ayuda en la comunidad.', 'Para hablar de actividades usa el presente simple: “We clean the park on Saturdays”. Para invitar: “Let\'s volunteer!”. También: “We should recycle”.',
        [['volunteer', 'voluntario, ser voluntario'], ['community center', 'centro comunitario'], ['festival', 'festival'], ['recycling', 'reciclaje'], ['garbage', 'basura'], ['clean-up', 'jornada de limpieza'], ['event', 'evento'], ['donate', 'donar']],
        ['They volunteer at the community center. — Ellos son voluntarios en el centro comunitario.', 'We should donate old clothes. — Deberíamos donar ropa vieja.'],
        [['People who help without payment are ___.', 'volunteers', 'neighbors', 'tickets', 'events', 'Quienes ayudan sin pago son voluntarios (volunteers).'], ['We put paper and plastic in the ___ bin.', 'recycling', 'bakery', 'traffic', 'festival', 'Se separa en el bote de reciclaje (recycling bin).']]),
      CapituloExtra('Describir mi ciudad', 'Aprender a describir cómo es tu ciudad y qué te gusta de ella.', 'Combina adjetivos y comparaciones: “My city is bigger than my town and it is very lively”. Usa “I like… because…” para dar razones.',
        [['crowded', 'lleno de gente'], ['safe', 'seguro'], ['lively', 'animado'], ['peaceful', 'pacífico'], ['modern', 'moderno'], ['historic', 'histórico'], ['downtown', 'centro de la ciudad'], ['suburb', 'suburbio']],
        ['My city is lively and modern. — Mi ciudad es animada y moderna.', 'I like my neighborhood because it is safe. — Me gusta mi colonia porque es segura.'],
        [['The streets are full of people. The city is very ___.', 'crowded', 'peaceful', 'empty', 'quiet', 'Lleno de gente se dice crowded.'], ['Mexico City has a lot of old buildings. It is a ___ city.', 'historic', 'suburb', 'downtown', 'garbage', 'Una ciudad con edificios antiguos es histórica (historic).']]),
    ]),
    UnidadExtra(31, 'Redes sociales y medios', false, [
      CapituloExtra('Perfiles y cuentas', 'Aprender a hablar de tu cuenta y tu perfil en redes sociales.', 'Para hablar de lo que tienes en una red usa “have” o el posesivo: “my profile”, “her account”. Para acciones habituales usa el presente simple: “I check my profile every day”. Con he/she/it el verbo lleva -s.',
        [['profile', 'perfil'], ['username', 'nombre de usuario'], ['account', 'cuenta'], ['password', 'contraseña'], ['follower', 'seguidor'], ['bio', 'biografía breve'], ['avatar', 'foto de perfil'], ['log in', 'iniciar sesión']],
        ['I created a new account yesterday. — Ayer creé una cuenta nueva.', 'She has ten thousand followers. — Ella tiene diez mil seguidores.', 'Please log in with your username. — Por favor inicia sesión con tu nombre de usuario.'],
        [['My sister ___ a new profile picture.', 'has', 'have', 'having', 'are', 'Con she/my sister el verbo have cambia a has.'], ['¿Qué significa “password”?', 'contraseña', 'seguidor', 'cuenta', 'perfil', 'Password es la contraseña que protege tu cuenta.']]),
      CapituloExtra('Publicar y compartir', 'Aprender a describir lo que publicas y compartes en línea.', 'Para contar lo que ya publicaste usa el pasado simple: “I posted a photo yesterday”. Los verbos regulares terminan en -ed y algunos son irregulares: “I took a selfie”. Para pedir algo usa “Can you share…?”.',
        [['post', 'publicación'], ['share', 'compartir'], ['upload', 'subir un archivo'], ['caption', 'pie de foto'], ['hashtag', 'etiqueta con #'], ['story', 'historia'], ['selfie', 'autofoto'], ['tag', 'etiquetar']],
        ['I uploaded a video last night. — Subí un video anoche.', 'Can you tag me in that photo? — ¿Puedes etiquetarme en esa foto?'],
        [['Yesterday I ___ a photo of my dog.', 'posted', 'post', 'posting', 'posts', 'Yesterday indica pasado simple: posted.'], ['A short text under a photo is called a ___.', 'caption', 'password', 'follower', 'selfie', 'Caption es el texto breve que acompaña una foto.']]),
      CapituloExtra('Reaccionar y comentar', 'Aprender a reaccionar a las publicaciones de otras personas.', 'Para opinar sobre una publicación usa “I think…” o “It looks…”: “It looks amazing!”. Para decir que algo te gusta o no, usa “like” y “don’t like”. Los comentarios suelen ser cortos y con emojis.',
        [['like', 'dar me gusta'], ['comment', 'comentario'], ['reply', 'responder'], ['emoji', 'emoticón'], ['react', 'reaccionar'], ['mention', 'mencionar'], ['message', 'mensaje'], ['block', 'bloquear']],
        ['She replied to my comment right away. — Ella respondió a mi comentario enseguida.', 'I don’t like spam messages. — No me gustan los mensajes spam.'],
        [['He ___ to my comment this morning.', 'replied', 'reply', 'replying', 'replies', 'This morning aquí se refiere al pasado: replied (y + ied).'], ['To stop someone from contacting you, you ___ them.', 'block', 'mention', 'tag', 'upload', 'Block significa bloquear a un usuario.']]),
      CapituloExtra('Noticias y periódicos', 'Aprender vocabulario para hablar de las noticias y los medios tradicionales.', 'Para hablar de noticias usa “read” o “watch”: “I read the news every morning”. “News” es incontable, así que lleva verbo en singular: “The news is bad”. Para una noticia concreta usa “a news story”.',
        [['news', 'noticias'], ['headline', 'titular'], ['article', 'artículo'], ['newspaper', 'periódico'], ['journalist', 'periodista'], ['broadcast', 'transmisión'], ['source', 'fuente'], ['editor', 'editor']],
        ['The news is on at nine o’clock. — Las noticias son a las nueve.', 'This journalist writes for a national newspaper. — Este periodista escribe para un periódico nacional.'],
        [['The news ___ very interesting today.', 'is', 'are', 'were', 'be', 'News es incontable y usa verbo singular: is.'], ['The title at the top of a news story is the ___.', 'headline', 'source', 'editor', 'broadcast', 'Headline es el titular de una nota.']]),
      CapituloExtra('Videos y podcasts', 'Aprender a hablar de videos, series y podcasts que ves o escuchas.', 'Para hablar de lo que estás viendo ahora usa el presente continuo: “I’m watching a series”. Para hábitos usa el presente simple con adverbios: “I usually listen to podcasts”. Después de “listen” va “to”.',
        [['stream', 'ver en línea'], ['episode', 'episodio'], ['subtitles', 'subtítulos'], ['podcast', 'pódcast'], ['subscribe', 'suscribirse'], ['trailer', 'avance'], ['playlist', 'lista de reproducción'], ['viral', 'viral']],
        ['I’m watching a new episode right now. — Estoy viendo un episodio nuevo ahora mismo.', 'I usually listen to a podcast on the bus. — Normalmente escucho un pódcast en el autobús.'],
        [['I always listen ___ music on my way to work.', 'to', 'at', 'for', 'in', 'El verbo listen se usa con la preposición to.'], ['Right now, she ___ a video.', 'is watching', 'watches', 'watch', 'watched', 'Right now pide presente continuo: is watching.']]),
      CapituloExtra('Seguridad y buenos hábitos', 'Aprender a dar consejos sobre privacidad y uso responsable de las redes.', 'Para dar consejos usa “should” + verbo base: “You should use a strong password”. Para prohibir o advertir usa “shouldn’t”: “You shouldn’t share private information”. “Should” no cambia con he/she/it.',
        [['privacy', 'privacidad'], ['scam', 'estafa'], ['fake', 'falso'], ['notification', 'notificación'], ['settings', 'configuración'], ['screen time', 'tiempo de pantalla'], ['addicted', 'adicto'], ['private', 'privado']],
        ['You should check your privacy settings. — Deberías revisar tu configuración de privacidad.', 'He shouldn’t trust fake accounts. — Él no debería confiar en cuentas falsas.'],
        [['You ___ share your password with anyone.', 'shouldn’t', 'shouldn’t to', 'don’t should', 'not should', 'La forma negativa correcta es shouldn’t + verbo base.'], ['An online trick to steal your money is a ___.', 'scam', 'trailer', 'caption', 'playlist', 'Scam significa estafa.']]),
    ]),
    UnidadExtra(32, 'Hobbies creativos y proyectos', false, [
      CapituloExtra('Mis pasatiempos creativos', 'Aprender a hablar de tus pasatiempos y de lo que disfrutas hacer.', 'Después de “enjoy”, “love” y “like” se puede usar un verbo con -ing: “I enjoy painting”. Para hablar de frecuencia usa “every weekend” o “once a week”. Para preguntar: “What do you do in your free time?”.',
        [['hobby', 'pasatiempo'], ['free time', 'tiempo libre'], ['creative', 'creativo'], ['enjoy', 'disfrutar'], ['painting', 'pintura'], ['drawing', 'dibujo'], ['craft', 'manualidad'], ['talent', 'talento']],
        ['I enjoy drawing in my free time. — Disfruto dibujar en mi tiempo libre.', 'She does crafts every weekend. — Ella hace manualidades cada fin de semana.'],
        [['I enjoy ___ pictures of animals.', 'drawing', 'draw', 'to drawing', 'drawn', 'Después de enjoy se usa el verbo con -ing.'], ['What do you do in your ___ time?', 'free', 'freely', 'freedom', 'frees', 'Free time es la expresión para tiempo libre.']]),
      CapituloExtra('Música y fotografía', 'Aprender a describir actividades artísticas como tocar música y tomar fotos.', 'Con instrumentos se usa “play the” + instrumento: “I play the guitar”. Para fotos se usa “take”: “I take photos of the city”. Con “can” hablas de habilidades: “She can sing very well”.',
        [['guitar', 'guitarra'], ['piano', 'piano'], ['sing', 'cantar'], ['song', 'canción'], ['camera', 'cámara'], ['photograph', 'fotografía'], ['lens', 'lente'], ['band', 'banda musical']],
        ['I play the piano every evening. — Toco el piano cada tarde.', 'He can take great photographs with an old camera. — Él puede tomar fotografías geniales con una cámara vieja.'],
        [['My brother plays ___ guitar in a band.', 'the', 'a the', 'to', 'at', 'Con instrumentos musicales se usa play the + instrumento.'], ['She ___ sing very well.', 'can', 'cans', 'is can', 'cannot to', 'Can no cambia con she y va seguido del verbo base.']]),
      CapituloExtra('Cocina, jardín y manualidades', 'Aprender vocabulario de actividades hechas a mano en casa.', 'Para dar instrucciones simples usa el imperativo: “Mix the flour and the eggs”. Para hablar de materiales usa “made of” o “made from”: “This bowl is made of clay”. Para el futuro cercano: “I’m going to bake a cake”.',
        [['bake', 'hornear'], ['recipe', 'receta'], ['garden', 'jardín'], ['seed', 'semilla'], ['knit', 'tejer'], ['yarn', 'estambre'], ['clay', 'arcilla'], ['sew', 'coser']],
        ['I’m going to bake a cake tomorrow. — Mañana voy a hornear un pastel.', 'My grandmother knits scarves with soft yarn. — Mi abuela teje bufandas con estambre suave.'],
        [['I’m ___ to plant some seeds this weekend.', 'going', 'go', 'went', 'goes', 'El futuro con going to usa am/is/are + going + to.'], ['This bowl is made ___ clay.', 'of', 'by', 'at', 'on', 'Se dice made of para indicar el material.']]),
      CapituloExtra('Planear un proyecto', 'Aprender a explicar qué proyecto quieres hacer y cómo lo planeas.', 'Para hablar de planes usa “I want to…” o “I’m planning to…”: “I’m planning to build a shelf”. Para decir el propósito usa “to” + verbo: “I need a saw to cut the wood”. Para dar pasos usa “first”, “then” y “finally”.',
        [['project', 'proyecto'], ['plan', 'plan'], ['idea', 'idea'], ['goal', 'meta'], ['deadline', 'fecha límite'], ['budget', 'presupuesto'], ['sketch', 'boceto'], ['step', 'paso']],
        ['I’m planning to start a new project. — Estoy planeando empezar un proyecto nuevo.', 'First, make a sketch. Then, buy the materials. — Primero, haz un boceto. Luego, compra los materiales.'],
        [['I’m planning ___ a wooden table.', 'to build', 'build', 'built', 'building to', 'Después de planning se usa to + verbo base.'], ['The last day to finish a project is the ___.', 'deadline', 'sketch', 'hobby', 'idea', 'Deadline es la fecha límite.']]),
      CapituloExtra('Herramientas y materiales', 'Aprender a pedir y nombrar herramientas y materiales para tus proyectos.', 'Para pedir algo usa “Could I borrow…?” o “Do you have…?”: “Could I borrow your hammer?”. Para hablar de cantidades usa “some” en afirmativas y “any” en preguntas y negativas: “I don’t have any glue”.',
        [['hammer', 'martillo'], ['scissors', 'tijeras'], ['glue', 'pegamento'], ['paint', 'pintura'], ['brush', 'pincel'], ['paper', 'papel'], ['wood', 'madera'], ['tool', 'herramienta']],
        ['Could I borrow your scissors, please? — ¿Podría pedirte prestadas tus tijeras, por favor?', 'I don’t have any glue at home. — No tengo nada de pegamento en casa.'],
        [['I don’t have ___ paper to draw on.', 'any', 'some', 'a', 'many of', 'En oraciones negativas se usa any.'], ['___ I borrow your hammer?', 'Could', 'Do', 'Am', 'Will to', 'Could I borrow…? es la forma cortés de pedir prestado.']]),
      CapituloExtra('Presentar tu trabajo', 'Aprender a mostrar y describir un proyecto terminado.', 'Para presentar tu trabajo usa el presente perfecto: “I have finished my painting”. Se forma con have/has + participio. Para describirlo usa adjetivos: “It’s colorful and unique”.',
        [['finished', 'terminado'], ['proud', 'orgulloso'], ['colorful', 'colorido'], ['unique', 'único'], ['exhibition', 'exposición'], ['display', 'exhibir'], ['feedback', 'opinión útil'], ['improve', 'mejorar']],
        ['I have finished my first painting. — He terminado mi primera pintura.', 'She is proud of her work. — Ella está orgullosa de su trabajo.', 'Can you give me some feedback? — ¿Puedes darme tu opinión?'],
        [['She ___ just finished her project.', 'has', 'have', 'is', 'does', 'El presente perfecto con she usa has + participio.'], ['I’m very proud ___ my work.', 'of', 'for', 'to', 'with by', 'El adjetivo proud va con la preposición of.']]),
    ]),
    UnidadExtra(33, 'Condicionales', true, [
      CapituloExtra('Zero conditional: verdades generales', 'Aprender a expresar hechos y verdades que siempre ocurren con if.', 'El zero conditional se forma con “if” + presente simple, y presente simple en la otra parte. Se usa para hechos científicos y rutinas: “If you heat ice, it melts”. “If” puede sustituirse por “when” sin cambiar el sentido.',
        [['if', 'si'], ['when', 'cuando'], ['whenever', 'siempre que'], ['unless', 'a menos que'], ['melt', 'derretirse'], ['boil', 'hervir'], ['freeze', 'congelarse'], ['always', 'siempre']],
        ['If you heat water to 100 degrees, it boils. — Si calientas agua a 100 grados, hierve.', 'If I drink coffee late, I can’t sleep. — Si tomo café tarde, no puedo dormir.'],
        [['If you mix blue and yellow, you ___ green.', 'get', 'will got', 'would get', 'getting', 'El zero conditional usa presente simple en ambas partes.'], ['If water ___ at 0°C, it turns into ice.', 'freezes', 'will freeze', 'froze', 'would freeze', 'Es un hecho general: presente simple con it, freezes.']]),
      CapituloExtra('First conditional: posibilidades reales', 'Aprender a hablar de situaciones futuras posibles y sus resultados.', 'El first conditional se forma con “if” + presente simple y “will” + verbo base en la otra parte. Habla de posibilidades reales en el futuro: “If it rains, we will stay home”. No se usa will justo después de “if”.',
        [['will', 'auxiliar de futuro'], ['won’t', 'no (futuro)'], ['as long as', 'siempre y cuando'], ['provided that', 'con tal de que'], ['in case', 'por si acaso'], ['probably', 'probablemente'], ['might', 'podría'], ['as soon as', 'tan pronto como']],
        ['If it rains tomorrow, we will stay home. — Si llueve mañana, nos quedaremos en casa.', 'If you study, you will pass the exam. — Si estudias, aprobarás el examen.', 'I’ll call you as soon as I arrive. — Te llamaré tan pronto como llegue.'],
        [['If she ___ early, she will catch the bus.', 'leaves', 'will leave', 'would leave', 'left', 'Después de if se usa presente simple, no will.'], ['If we hurry, we ___ on time.', 'will arrive', 'arrive to', 'would arrived', 'arrived', 'La parte principal del first conditional usa will + verbo base.']]),
      CapituloExtra('Second conditional: situaciones imaginarias', 'Aprender a hablar de situaciones poco probables o imaginarias en el presente.', 'El second conditional se forma con “if” + pasado simple y “would” + verbo base. Se usa para situaciones irreales o poco probables: “If I won the lottery, I would travel”. Con “be” se acepta “were” para todas las personas: “If I were you…”.',
        [['would', 'auxiliar condicional'], ['were', 'fuera (subjuntivo)'], ['imagine', 'imaginar'], ['lottery', 'lotería'], ['rich', 'rico'], ['suppose', 'suponer'], ['unlikely', 'poco probable'], ['advice', 'consejo']],
        ['If I won the lottery, I would travel the world. — Si ganara la lotería, viajaría por el mundo.', 'If I were you, I would talk to her. — Yo en tu lugar hablaría con ella.'],
        [['If I ___ rich, I would buy a big house.', 'were', 'will be', 'am', 'would be', 'El second conditional usa pasado simple tras if; con be se usa were.'], ['If she had more time, she ___ a book.', 'would write', 'will write', 'wrote', 'writes', 'La parte principal usa would + verbo base.']]),
      CapituloExtra('Third conditional: lo que no pasó', 'Aprender a hablar de situaciones pasadas que no ocurrieron y sus consecuencias.', 'El third conditional se forma con “if” + past perfect y “would have” + participio. Imagina un pasado diferente: “If I had studied, I would have passed”. Se usa para lamentos, críticas y reflexiones sobre el pasado.',
        [['had studied', 'hubiera estudiado'], ['would have', 'habría'], ['could have', 'habría podido'], ['regret', 'arrepentimiento'], ['missed', 'perdí (un tren)'], ['failed', 'reprobó'], ['mistake', 'error'], ['luckily', 'por suerte']],
        ['If I had left earlier, I wouldn’t have missed the train. — Si hubiera salido antes, no habría perdido el tren.', 'If they had listened, they would have understood. — Si hubieran escuchado, habrían entendido.'],
        [['If he had studied, he ___ the exam.', 'would have passed', 'would pass', 'will have passed', 'had passed', 'El third conditional usa would have + participio.'], ['If we ___ the map, we wouldn’t have got lost.', 'had checked', 'checked', 'would check', 'have checked', 'Después de if va past perfect: had checked.']]),
      CapituloExtra('Wish e if only', 'Aprender a expresar deseos y lamentos con wish e if only.', 'Para deseos sobre el presente usa “wish” + pasado simple: “I wish I had a car”. Para lamentos sobre el pasado usa “wish” + past perfect: “I wish I had gone”. Con “if only” el sentido es más fuerte: “If only I knew!”.',
        [['wish', 'desear'], ['if only', 'ojalá'], ['hope', 'esperar'], ['dream', 'sueño'], ['wished', 'deseé'], ['had gone', 'hubiera ido'], ['annoyed', 'molesto'], ['complain', 'quejarse']],
        ['I wish I had more free time. — Ojalá tuviera más tiempo libre.', 'She wishes she had gone to the party. — Ella desea haber ido a la fiesta.', 'If only I knew the answer! — ¡Si tan solo supiera la respuesta!'],
        [['I wish I ___ speak French.', 'could', 'can', 'will', 'am able', 'Wish para el presente lleva pasado: could.'], ['I wish I ___ to the concert last night.', 'had gone', 'went', 'would go', 'have gone', 'Para lamentos del pasado se usa wish + past perfect.']]),
      CapituloExtra('Condicionales mixtos y práctica', 'Aprender a combinar condicionales para mezclar pasado y presente.', 'Un condicional mixto combina tiempos. Pasado que afecta al presente: “If I had taken the job, I would be rich now”. Situación presente que habría cambiado el pasado: “If I were braver, I would have said yes”.',
        [['mixed', 'mixto'], ['result', 'resultado'], ['past', 'pasado'], ['present', 'presente'], ['would be', 'sería'], ['nowadays', 'hoy en día'], ['otherwise', 'de lo contrario'], ['instead', 'en cambio']],
        ['If I had taken that job, I would be rich now. — Si hubiera aceptado ese trabajo, ahora sería rico.', 'If she were more careful, she wouldn’t have broken it. — Si fuera más cuidadosa, no lo habría roto.'],
        [['If I had slept more, I ___ tired now.', 'wouldn’t be', 'won’t be', 'wouldn’t have been', 'am not', 'Pasado que afecta al presente: had + participio y would + verbo base.'], ['If he ___ taller, he would have joined the team.', 'were', 'had be', 'will be', 'is', 'Condición presente: pasado simple (were); resultado pasado: would have.']]),
    ]),
    UnidadExtra(34, 'Voz pasiva', true, [
      CapituloExtra('Pasiva en presente simple', 'Aprender a formar la voz pasiva en presente simple.', 'La pasiva se forma con “be” + participio pasado. En presente simple usa am/is/are: “English is spoken here”. Se usa cuando importa más la acción o el objeto que quién la hace.',
        [['is made', 'se hace'], ['are sold', 'se venden'], ['is spoken', 'se habla'], ['is used', 'se usa'], ['are grown', 'se cultivan'], ['is called', 'se llama'], ['are produced', 'se producen'], ['participle', 'participio']],
        ['Coffee is grown in Colombia. — El café se cultiva en Colombia.', 'These shoes are made in Mexico. — Estos zapatos se fabrican en México.'],
        [['Spanish ___ in many countries.', 'is spoken', 'speaks', 'is speak', 'are spoken', 'Spanish es singular: is + participio spoken.'], ['These cars ___ in Germany.', 'are made', 'is made', 'make', 'are make', 'Cars es plural: are + participio made.']]),
      CapituloExtra('Pasiva en pasado simple', 'Aprender a usar la pasiva para hablar de hechos del pasado.', 'En pasado simple se usa was/were + participio: “The house was built in 1990”. Con sujeto singular va “was” y con plural “were”. Es común para historia, noticias y descubrimientos.',
        [['was built', 'fue construido'], ['were invented', 'fueron inventados'], ['was written', 'fue escrito'], ['was born', 'nació'], ['was found', 'fue encontrado'], ['were stolen', 'fueron robados'], ['was painted', 'fue pintado'], ['was discovered', 'fue descubierto']],
        ['The telephone was invented in the nineteenth century. — El teléfono fue inventado en el siglo XIX.', 'My bike was stolen last night. — Mi bicicleta fue robada anoche.'],
        [['The painting ___ by a famous artist.', 'was painted', 'were painted', 'is paint', 'painted was', 'Painting es singular y pasado: was + painted.'], ['Two windows ___ broken during the storm.', 'were', 'was', 'is', 'be', 'Windows es plural en pasado: were.']]),
      CapituloExtra('Pasiva en futuro', 'Aprender a formar la pasiva con will y going to.', 'En futuro se usa “will be” + participio: “The report will be finished tomorrow”. También se puede usar “is/are going to be” + participio. La negación es “won’t be”.',
        [['will be done', 'será hecho'], ['will be sent', 'será enviado'], ['will be held', 'se celebrará'], ['will be announced', 'se anunciará'], ['going to be', 'va a ser'], ['will be delivered', 'será entregado'], ['won’t be', 'no será'], ['will be cancelled', 'será cancelado']],
        ['The results will be announced on Friday. — Los resultados se anunciarán el viernes.', 'The package is going to be delivered tomorrow. — El paquete va a ser entregado mañana.'],
        [['The meeting ___ next Monday.', 'will be held', 'will hold', 'will be hold', 'is held will', 'Pasiva en futuro: will be + participio held.'], ['The invitations ___ tomorrow.', 'will be sent', 'will sent', 'are sent will', 'will be send', 'Se necesita will be + participio sent.']]),
      CapituloExtra('Pasiva con modales', 'Aprender a usar la pasiva con can, must, should y might.', 'Con modales la pasiva se forma con modal + be + participio: “This door must be closed”. Sirve para reglas, obligaciones, consejos y posibilidades. La negación va en el modal: “It can’t be repaired”.',
        [['can be done', 'puede hacerse'], ['must be kept', 'debe guardarse'], ['should be cleaned', 'debería limpiarse'], ['might be late', 'podría llegar tarde'], ['may be used', 'puede usarse'], ['could be solved', 'podría resolverse'], ['has to be paid', 'tiene que pagarse'], ['can’t be repaired', 'no puede repararse']],
        ['The form must be signed by everyone. — El formulario debe ser firmado por todos.', 'This problem can be solved easily. — Este problema puede resolverse fácilmente.'],
        [['Seat belts ___ worn at all times.', 'must be', 'must are', 'must been', 'must being', 'Con modales la pasiva usa modal + be + participio.'], ['The room should ___ cleaned every day.', 'be', 'is', 'been', 'being', 'Después de un modal va el verbo base be.']]),
      CapituloExtra('El agente con by', 'Aprender cuándo mencionar quién realiza la acción en la pasiva.', 'Se usa “by” + agente cuando es información importante: “Hamlet was written by Shakespeare”. Si el agente es obvio, desconocido o irrelevante, se omite: “My car was stolen”. De la voz activa a la pasiva, el objeto pasa a ser sujeto.',
        [['by', 'por (agente)'], ['agent', 'agente'], ['active voice', 'voz activa'], ['passive voice', 'voz pasiva'], ['subject', 'sujeto'], ['object', 'objeto'], ['obvious', 'obvio'], ['unknown', 'desconocido']],
        ['The novel was written by a young author. — La novela fue escrita por un autor joven.', 'The bank was robbed last week. — El banco fue asaltado la semana pasada.'],
        [['Active: Picasso painted this picture. Passive: This picture ___ by Picasso.', 'was painted', 'painted', 'is painted was', 'was paint', 'El pasado activo painted pasa a was + painted.'], ['When the person doing the action is unknown, we usually ___ the agent.', 'omit', 'repeat', 'double', 'capitalize', 'Si el agente es desconocido, normalmente se omite con by.']]),
      CapituloExtra('Usos comunes y práctica', 'Aprender a reconocer los usos más frecuentes de la pasiva en la vida real.', 'La pasiva es frecuente en avisos, noticias, procesos y textos formales: “Visitors are asked to sign in”. Con verbos como give hay dos pasivas: “She was given a prize”. También se usa “get” de manera informal: “He got fired”.',
        [['is required', 'se requiere'], ['is allowed', 'está permitido'], ['is expected', 'se espera'], ['was given', 'le dieron'], ['got fired', 'fue despedido'], ['is known as', 'es conocido como'], ['was told', 'le dijeron'], ['is said', 'se dice']],
        ['Smoking is not allowed here. — Aquí no se permite fumar.', 'He was given a new laptop by his company. — Su empresa le dio una laptop nueva.', 'She got promoted last month. — La ascendieron el mes pasado.'],
        [['Passengers ___ to arrive two hours before the flight.', 'are expected', 'expect', 'is expected', 'are expecting be', 'Passengers es plural: are + expected.'], ['She ___ a medal for her work.', 'was given', 'gave', 'were given', 'is give', 'She es singular y el hecho es pasado: was given.']]),
    ]),
    UnidadExtra(35, 'Estilo indirecto', true, [
      CapituloExtra('Estilo directo e indirecto', 'Aprender la diferencia entre citar y reportar lo que alguien dijo.', 'El estilo directo cita las palabras exactas: “She said, ‘I am tired’”. El estilo indirecto las reporta sin comillas: “She said that she was tired”. Cambian los pronombres y normalmente el tiempo verbal; “that” es opcional.',
        [['said', 'dijo'], ['that', 'que (conjunción)'], ['quote', 'citar'], ['report', 'reportar'], ['exact words', 'palabras exactas'], ['pronoun', 'pronombre'], ['direct speech', 'estilo directo'], ['reported speech', 'estilo indirecto']],
        ['Direct: Tom said, “I like pizza.” Reported: Tom said he liked pizza. — Tom dijo que le gustaba la pizza.', 'She said that she was tired. — Ella dijo que estaba cansada.'],
        [['Direct: “I live in Lima,” she said. Reported: She said she ___ in Lima.', 'lived', 'lives', 'will live', 'living', 'El presente simple retrocede a pasado simple: lived.'], ['Direct: “I am happy,” he said. Reported: He said ___ happy.', 'he was', 'I was', 'I am', 'was he', 'El pronombre cambia a he y am pasa a was.']]),
      CapituloExtra('Retroceso de tiempos verbales', 'Aprender cómo cambian los tiempos verbales al reportar.', 'Al reportar, el tiempo suele retroceder: presente simple → pasado simple, presente continuo → pasado continuo, pasado simple → past perfect, will → would, can → could. Ejemplo: “‘I will help’ → He said he would help”.',
        [['backshift', 'retroceso de tiempo'], ['would', 'forma pasada de will'], ['could', 'forma pasada de can'], ['had done', 'había hecho'], ['was doing', 'estaba haciendo'], ['might', 'forma pasada de may'], ['had been', 'había sido'], ['must', 'deber']],
        ['“I’m working,” she said. → She said she was working. — Ella dijo que estaba trabajando.', '“I will call you,” he said. → He said he would call me. — Él dijo que me llamaría.'],
        [['“I can swim,” he said. → He said he ___ swim.', 'could', 'can', 'will', 'cans', 'Can retrocede a could.'], ['“We went to Paris,” they said. → They said they ___ to Paris.', 'had gone', 'went to', 'have gone', 'would go', 'El pasado simple retrocede a past perfect: had gone.']]),
      CapituloExtra('Cambios de tiempo y lugar', 'Aprender a cambiar expresiones de tiempo, lugar y demostrativos al reportar.', 'Cuando el momento o lugar cambia, las expresiones también: today → that day, tomorrow → the next day, yesterday → the day before, here → there, this → that. Ejemplo: “‘I’ll come tomorrow’ → She said she would come the next day”.',
        [['that day', 'ese día'], ['the next day', 'al día siguiente'], ['the day before', 'el día anterior'], ['there', 'allí'], ['then', 'entonces'], ['the following week', 'la semana siguiente'], ['the previous year', 'el año anterior'], ['ago', 'hace (tiempo)']],
        ['“I’ll see you tomorrow,” he said. → He said he would see me the next day. — Dijo que me vería al día siguiente.', '“I was here yesterday,” she said. → She said she had been there the day before. — Dijo que había estado allí el día anterior.'],
        [['“I’ll leave tomorrow,” she said. → She said she would leave ___.', 'the next day', 'tomorrow', 'yesterday', 'today', 'Tomorrow cambia a the next day en estilo indirecto.'], ['“I like it here,” he said. → He said he liked it ___.', 'there', 'here', 'where', 'then', 'Here cambia a there.']]),
      CapituloExtra('Preguntas en estilo indirecto', 'Aprender a reportar preguntas de sí/no y de información.', 'Las preguntas de sí/no se reportan con “if” o “whether”: “She asked if I was ready”. Las de información conservan la palabra interrogativa: “He asked where I lived”. El orden es el de una oración afirmativa, sin do/does/did.',
        [['asked', 'preguntó'], ['whether', 'si (o no)'], ['wondered', 'se preguntó'], ['wanted to know', 'quería saber'], ['where', 'dónde'], ['why', 'por qué'], ['how', 'cómo'], ['what', 'qué']],
        ['She asked me if I was ready. — Ella me preguntó si estaba listo.', 'He asked where I lived. — Él preguntó dónde vivía yo.'],
        [['“Do you like tea?” she asked. → She asked me ___ tea.', 'if I liked', 'did I like', 'that I liked', 'if did I like', 'Las preguntas sí/no usan if y orden afirmativo, sin did.'], ['“Where do you work?” he asked. → He asked me where ___.', 'I worked', 'did I work', 'I work did', 'do I work', 'Orden afirmativo y retroceso a pasado: I worked.']]),
      CapituloExtra('Órdenes, peticiones y consejos', 'Aprender a reportar órdenes, peticiones y consejos con infinitivo.', 'Las órdenes y peticiones se reportan con verbo + objeto + “to” + infinitivo: “She told me to sit down”. En negativo se usa “not to”: “He told us not to talk”. Para peticiones se usa “asked” y para consejos “advised”.',
        [['told', 'dijo (ordenó)'], ['ordered', 'ordenó'], ['begged', 'suplicó'], ['advised', 'aconsejó'], ['warned', 'advirtió'], ['reminded', 'recordó'], ['not to', 'que no'], ['invited', 'invitó']],
        ['The teacher told us to open our books. — La maestra nos dijo que abriéramos los libros.', 'He asked me not to be late. — Me pidió que no llegara tarde.'],
        [['“Close the door,” she said. → She told me ___ the door.', 'to close', 'close', 'that close', 'closing to', 'Las órdenes se reportan con told + objeto + to + verbo.'], ['“Don’t touch it,” he said. → He told me ___ it.', 'not to touch', 'to not touched', 'don’t touch', 'no touching to', 'La orden negativa usa not to + verbo base.']]),
      CapituloExtra('Say, tell y verbos de reporte', 'Aprender a usar say y tell y otros verbos para reportar con precisión.', 'Después de “tell” va siempre una persona: “He told me”. Con “say” no se usa objeto directo: “He said he was busy”. Otros verbos reflejan la intención: “She promised to call”, “He denied taking it”.',
        [['promised', 'prometió'], ['denied', 'negó'], ['admitted', 'admitió'], ['suggested', 'sugirió'], ['explained', 'explicó'], ['refused', 'se negó'], ['agreed', 'estuvo de acuerdo'], ['complained', 'se quejó']],
        ['She promised to call me later. — Ella prometió llamarme más tarde.', 'He admitted that he had made a mistake. — Él admitió que había cometido un error.', 'They refused to help us. — Se negaron a ayudarnos.'],
        [['He ___ me that he was tired.', 'told', 'said', 'said to that', 'tell', 'Tell lleva objeto de persona directamente: told me.'], ['She ___ to help me with my homework.', 'promised', 'denied', 'admitted', 'suggested', 'Promised + to + infinitivo expresa una promesa.']]),
    ]),
    UnidadExtra(36, 'Inglés para viajes de negocios', true, [
      CapituloExtra('Vuelos y hoteles', 'Aprender a reservar vuelos y alojamiento para un viaje de trabajo.', 'Para pedir una reserva usa “I’d like to + verbo” o “Could I + verbo?”, que suenan profesionales. Para hablar de un plan fijo usa el presente continuo: “I’m flying to Chicago on Monday”.',
        [['book', 'reservar'], ['itinerary', 'itinerario'], ['layover', 'escala'], ['boarding pass', 'pase de abordar'], ['round trip', 'viaje redondo'], ['aisle seat', 'asiento de pasillo'], ['check-in', 'registro de entrada'], ['upgrade', 'mejora de categoría']],
        ['I’d like to book a round trip to Boston. — Quisiera reservar un viaje redondo a Boston.', 'Could I get an aisle seat, please? — ¿Me podría dar un asiento de pasillo, por favor?', 'My layover in Dallas is two hours long. — Mi escala en Dallas dura dos horas.'],
        [['I’d like to ___ a flight to London for next Tuesday.', 'book', 'booked', 'booking', 'books', 'Después de “I’d like to” se usa el verbo en forma base: book.'], ['What do you call a stop between two flights?', 'a layover', 'an upgrade', 'a boarding pass', 'an itinerary', 'Layover es la escala entre dos vuelos.']]),
      CapituloExtra('Aeropuerto y aduana', 'Aprender a desenvolverte en el aeropuerto y responder en la aduana.', 'En la aduana te harán preguntas como “What is the purpose of your visit?”. Responde con “I’m here for + sustantivo” o “I’m here to + verbo”: “I’m here for a conference”.',
        [['customs', 'aduana'], ['carry-on', 'equipaje de mano'], ['luggage', 'equipaje'], ['security', 'control de seguridad'], ['gate', 'puerta de embarque'], ['delay', 'retraso'], ['passport', 'pasaporte'], ['declare', 'declarar']],
        ['Do you have anything to declare? — ¿Tiene algo que declarar?', 'My flight has a two-hour delay. — Mi vuelo tiene dos horas de retraso.', 'I’m here for a business conference. — Vengo a una conferencia de negocios.'],
        [['I’m here ___ a sales meeting.', 'for', 'at', 'by', 'from', 'Con un sustantivo para indicar el motivo se usa “here for”.'], ['At the airport, where do you show your passport and answer questions about your trip?', 'at customs', 'at the gate', 'at the carry-on', 'at the delay', 'Las preguntas sobre el viaje y los documentos se hacen en la aduana (customs).']]),
      CapituloExtra('Reuniones y presentaciones', 'Aprender a participar en reuniones y presentar ideas con claridad.', 'Para abrir una presentación usa frases como “Let me start by…” o “I’d like to walk you through…”. Para cerrar usa “To sum up…”: “To sum up, we need to approve the proposal this week”.',
        [['agenda', 'orden del día'], ['attend', 'asistir'], ['deadline', 'fecha límite'], ['proposal', 'propuesta'], ['colleague', 'colega'], ['schedule', 'programar'], ['minutes', 'acta de la reunión'], ['follow up', 'dar seguimiento']],
        ['Let me walk you through our proposal. — Permítanme explicarles nuestra propuesta paso a paso.', 'Could you send me the minutes of the meeting? — ¿Podrías enviarme el acta de la reunión?', 'We need to follow up with the client tomorrow. — Necesitamos dar seguimiento al cliente mañana.'],
        [['The ___ for this project is Friday, so we must hurry.', 'deadline', 'agenda', 'minutes', 'colleague', 'Deadline es la fecha límite.'], ['Which phrase is used to close a presentation?', 'To sum up, we need more time.', 'Let me start by saying hello.', 'I’d like to book a seat.', 'Where is the gate?', '“To sum up” se usa para resumir y cerrar.']]),
      CapituloExtra('Networking y presentaciones', 'Aprender a presentarte, conversar y hacer contactos profesionales.', 'Para presentarte usa “Nice to meet you. I’m… and I work in…”. Para hacer plática ligera pregunta “What brings you to the event?”. Para despedirte con buen modo: “It was a pleasure meeting you”.',
        [['pleasure', 'placer'], ['acquaintance', 'conocido'], ['small talk', 'plática ligera'], ['connection', 'contacto'], ['conference', 'congreso'], ['booth', 'módulo de exhibición'], ['exchange', 'intercambiar'], ['reach out', 'ponerse en contacto']],
        ['It was a pleasure meeting you. — Fue un placer conocerte.', 'Let’s exchange business cards. — Intercambiemos tarjetas de presentación.', 'I’ll reach out to you next week. — Me pondré en contacto contigo la próxima semana.'],
        [['It was a ___ to meet you.', 'pleasure', 'booth', 'connection', 'layover', 'La expresión fija es “a pleasure to meet you”.'], ['What is “small talk”?', 'Casual conversation about light topics', 'A very short flight', 'A small office', 'A legal contract', 'Small talk es la plática informal sobre temas ligeros.']]),
      CapituloExtra('Comidas con clientes', 'Aprender a reservar, pedir y pagar durante una comida de negocios.', 'Para ofrecer algo usa “Would you like…?” y para recomendar “I’d recommend the…”. Al pagar puedes decir “It’s on me” o “Let’s split the bill”: “I’d recommend the salmon”.',
        [['reservation', 'reservación'], ['appetizer', 'entrada'], ['bill', 'cuenta'], ['tip', 'propina'], ['recommend', 'recomendar'], ['vegetarian', 'vegetariano'], ['allergic', 'alérgico'], ['split', 'dividir']],
        ['I have a reservation for four at seven. — Tengo una reservación para cuatro a las siete.', 'I’m allergic to nuts. — Soy alérgico a las nueces.', 'Let’s split the bill. — Dividamos la cuenta.'],
        [['Could we have the ___, please? We’re ready to pay.', 'bill', 'appetizer', 'reservation', 'tip', 'Para pedir que traigan la cuenta se dice “the bill”.'], ['I’m ___ to shellfish, so I can’t order the shrimp.', 'allergic', 'vegetarian', 'reserved', 'recommended', 'Be allergic to significa ser alérgico a algo.']]),
      CapituloExtra('Gastos y correos de viaje', 'Aprender a gestionar gastos y escribir correos formales después del viaje.', 'Los correos formales abren con “Dear Ms. Lopez,” y cierran con “Best regards,”. Para pedir un reembolso usa “I’m writing to request…”: “I’m writing to request reimbursement for my travel expenses”.',
        [['expense report', 'reporte de gastos'], ['receipt', 'recibo'], ['reimburse', 'reembolsar'], ['invoice', 'factura'], ['budget', 'presupuesto'], ['approve', 'aprobar'], ['per diem', 'viáticos diarios'], ['claim', 'solicitar un reembolso']],
        ['Please attach every receipt to the expense report. — Por favor adjunta todos los recibos al reporte de gastos.', 'The company will reimburse me for the hotel. — La empresa me reembolsará el hotel.', 'I’m writing to request approval of the budget. — Le escribo para solicitar la aprobación del presupuesto.'],
        [['The company will ___ me for the taxi fare.', 'reimburse', 'approve', 'attend', 'book', 'Reimburse significa reembolsar un gasto a alguien.'], ['Which closing is appropriate for a formal email?', 'Best regards,', 'See ya!', 'Whatever,', 'Bye bye buddy,', '“Best regards” es un cierre formal adecuado.']]),
    ]),
    UnidadExtra(37, 'Cultura y costumbres del mundo', true, [
      CapituloExtra('Saludos y etiqueta', 'Aprender a describir saludos y reglas de cortesía en distintos países.', 'Para hablar de costumbres usa el presente simple con “In + país, people…”: “In Japan, people bow to greet each other”. Para consejos usa “should” o “it’s polite to + verbo”.',
        [['greeting', 'saludo'], ['handshake', 'apretón de manos'], ['bow', 'hacer una reverencia'], ['custom', 'costumbre'], ['etiquette', 'etiqueta'], ['polite', 'cortés'], ['tradition', 'tradición'], ['gesture', 'gesto']],
        ['In Japan, people bow to greet each other. — En Japón, la gente hace una reverencia para saludarse.', 'A firm handshake is common in the United States. — Un apretón de manos firme es común en Estados Unidos.', 'It’s polite to arrive on time in Germany. — Es cortés llegar a tiempo en Alemania.'],
        [['In Japan, people ___ to greet each other.', 'bow', 'bows', 'bowing', 'bowed to', 'Con el sujeto plural “people” el presente simple usa la forma base: bow.'], ['Which word means “reglas de buena conducta social”?', 'etiquette', 'handshake', 'gesture', 'greeting', 'Etiquette son las normas de cortesía social.']]),
      CapituloExtra('Festivales y celebraciones', 'Aprender a hablar de fiestas y celebraciones tradicionales.', 'Para describir una celebración usa el presente simple para hechos habituales: “Families gather every year”. Con “is celebrated” usas la voz pasiva: “Diwali is celebrated in October or November”.',
        [['festival', 'festival'], ['parade', 'desfile'], ['fireworks', 'fuegos artificiales'], ['ceremony', 'ceremonia'], ['lantern', 'farol'], ['harvest', 'cosecha'], ['costume', 'disfraz'], ['celebrate', 'celebrar']],
        ['Diwali is celebrated with lanterns and fireworks. — El Diwali se celebra con faroles y fuegos artificiales.', 'People wear colorful costumes in the parade. — La gente usa disfraces coloridos en el desfile.', 'The harvest festival takes place every autumn. — El festival de la cosecha se realiza cada otoño.'],
        [['This festival ___ in many countries every year.', 'is celebrated', 'celebrates', 'is celebrating', 'celebrate', 'Para decir “se celebra” se usa la voz pasiva: is celebrated.'], ['People enjoy the colorful ___ down the main street.', 'parade', 'harvest', 'etiquette', 'ceremony of', 'Parade es un desfile que avanza por la calle.']]),
      CapituloExtra('Comida y mesa', 'Aprender a describir platillos y costumbres a la hora de comer.', 'Para describir un platillo usa adjetivos y “It is made of / with…”: “This dish is made with rice and beans”. Para hablar de costumbres usa “In… people usually eat with…”.',
        [['cuisine', 'cocina típica'], ['chopsticks', 'palillos chinos'], ['dish', 'platillo'], ['spicy', 'picante'], ['feast', 'banquete'], ['staple', 'alimento básico'], ['street food', 'comida callejera'], ['utensils', 'cubiertos']],
        ['Rice is a staple food in many Asian countries. — El arroz es un alimento básico en muchos países asiáticos.', 'Mexican cuisine is famous for its spicy dishes. — La cocina mexicana es famosa por sus platillos picantes.', 'In Korea, people eat with chopsticks and a spoon. — En Corea, la gente come con palillos y cuchara.'],
        [['In China, many people eat with ___.', 'chopsticks', 'feasts', 'staples', 'cuisine', 'Los palillos chinos se dicen chopsticks.'], ['This dish is made ___ corn and beans.', 'with', 'by', 'on', 'at', 'Para los ingredientes se usa “made with”.']]),
      CapituloExtra('Religión y creencias', 'Aprender a hablar de creencias y lugares sagrados con respeto.', 'Para hablar de creencias usa “believe in” y “follow”: “Many people believe in a higher power”. Usa un tono neutral y respetuoso con frases como “Some people…” o “Followers of this religion…”.',
        [['belief', 'creencia'], ['temple', 'templo'], ['pray', 'rezar'], ['ritual', 'ritual'], ['sacred', 'sagrado'], ['pilgrimage', 'peregrinación'], ['faith', 'fe'], ['holy', 'santo']],
        ['Millions of people make a pilgrimage to Mecca. — Millones de personas hacen una peregrinación a La Meca.', 'Many people pray in the temple every morning. — Muchas personas rezan en el templo cada mañana.', 'The river is sacred to millions of people. — El río es sagrado para millones de personas.'],
        [['Many people ___ in a higher power.', 'believe', 'pray', 'bow', 'follow of', 'La construcción correcta es “believe in”.'], ['A place that is very important in a religion is called ___.', 'sacred', 'spicy', 'polite', 'casual', 'Sacred describe lo que es sagrado.']]),
      CapituloExtra('Choque cultural', 'Aprender a expresar experiencias de adaptación a otra cultura.', 'Para hablar de acostumbrarte usa “get used to + -ing”: “I’m getting used to eating dinner late”. Para algo que hacías antes usa “used to + verbo”: “I used to eat dinner early”.',
        [['culture shock', 'choque cultural'], ['stereotype', 'estereotipo'], ['adapt', 'adaptarse'], ['misunderstanding', 'malentendido'], ['background', 'origen, formación'], ['diverse', 'diverso'], ['respect', 'respeto'], ['heritage', 'herencia cultural']],
        ['I had culture shock when I moved to Canada. — Tuve choque cultural cuando me mudé a Canadá.', 'I’m getting used to living in a new country. — Me estoy acostumbrando a vivir en un país nuevo.', 'A stereotype can cause a misunderstanding. — Un estereotipo puede causar un malentendido.'],
        [['I’m getting used to ___ with my host family.', 'living', 'live', 'lived', 'to live', 'Después de “get used to” se usa el verbo en -ing.'], ['What is a “stereotype”?', 'A fixed, oversimplified idea about a group', 'A traditional meal', 'A religious ceremony', 'A kind of greeting', 'Un estereotipo es una idea simplificada y fija sobre un grupo.']]),
      CapituloExtra('Comparar culturas', 'Aprender a comparar y contrastar costumbres de diferentes culturas.', 'Para contrastar usa “whereas”, “while” y “unlike”: “Unlike Spain, the US has early dinners”. Para semejanzas usa “similar to”, “both” y “in the same way”.',
        [['whereas', 'mientras que'], ['unlike', 'a diferencia de'], ['similarity', 'similitud'], ['difference', 'diferencia'], ['contrast', 'contraste'], ['common', 'común'], ['typical', 'típico'], ['widespread', 'muy extendido']],
        ['Dinner is early in the US, whereas it is late in Spain. — La cena es temprano en EE. UU., mientras que en España es tarde.', 'Unlike my country, people here rarely kiss when they greet. — A diferencia de mi país, aquí la gente rara vez se besa al saludar.', 'Soccer is widespread in Latin America. — El futbol está muy extendido en Latinoamérica.'],
        [['Tea is typical in England, ___ coffee is more popular in Brazil.', 'whereas', 'unlike', 'similarity', 'both', '“Whereas” une dos ideas contrastantes en una oración.'], ['___ my city, this town is very quiet.', 'Unlike', 'Whereas', 'Similar', 'Both', '“Unlike” va seguido de un sustantivo y significa a diferencia de.']]),
    ]),
    UnidadExtra(38, 'Finanzas personales', true, [
      CapituloExtra('Ingresos y presupuesto', 'Aprender a hablar de dinero, ingresos y gastos mensuales.', 'Para hablar de tu dinero usa verbos como “earn”, “spend” y “pay”: “I earn \$2,000 a month and I spend \$1,500”. Un presupuesto compara lo que entra con lo que sale.',
        [['income', 'ingreso'], ['expense', 'gasto'], ['budget', 'presupuesto'], ['salary', 'sueldo'], ['bills', 'recibos, cuentas'], ['rent', 'renta'], ['groceries', 'despensa'], ['savings', 'ahorros']],
        ['My monthly income is higher than my expenses. — Mi ingreso mensual es mayor que mis gastos.', 'I pay the bills on the first of the month. — Pago las cuentas el primero de mes.', 'Rent is my biggest expense. — La renta es mi mayor gasto.'],
        [['I ___ \$3,000 a month at my job.', 'earn', 'borrow', 'invest', 'owe', 'Earn significa ganar dinero por trabajar.'], ['What is a budget?', 'A plan for how to spend and save money', 'A type of loan', 'A bank card', 'A kind of tax', 'Un presupuesto es un plan de gastos y ahorro.']]),
      CapituloExtra('Ahorro e inversión', 'Aprender a explicar cómo hacer crecer tu dinero.', 'Para hablar de metas usa “in order to” o “so that”: “I save every month so that I can retire early”. Invertir implica riesgo: “The higher the return, the higher the risk”.',
        [['invest', 'invertir'], ['interest', 'interés'], ['stock', 'acción'], ['bond', 'bono'], ['retirement', 'jubilación'], ['portfolio', 'portafolio de inversión'], ['dividend', 'dividendo'], ['emergency fund', 'fondo de emergencia']],
        ['I put some money into stocks and bonds. — Puse algo de dinero en acciones y bonos.', 'Every worker should have an emergency fund. — Todo trabajador debería tener un fondo de emergencia.', 'The account pays three percent interest. — La cuenta paga tres por ciento de interés.'],
        [['I save money every month ___ I can retire early.', 'so that', 'because of', 'although', 'unless', '“So that” introduce el propósito de la acción.'], ['What is an emergency fund?', 'Money saved for unexpected problems', 'A loan from a bank', 'A type of stock', 'A monthly bill', 'El fondo de emergencia es dinero guardado para imprevistos.']]),
      CapituloExtra('Banco y tarjetas', 'Aprender a usar el vocabulario de cuentas, tarjetas y operaciones bancarias.', 'Para hacer operaciones usa “I’d like to + verbo”: “I’d like to open a checking account”. Para pedir datos usa “What’s my balance?” o “How much is the fee?”.',
        [['checking account', 'cuenta de cheques'], ['debit card', 'tarjeta de débito'], ['credit card', 'tarjeta de crédito'], ['withdraw', 'retirar'], ['deposit', 'depositar'], ['balance', 'saldo'], ['overdraft', 'sobregiro'], ['ATM', 'cajero automático']],
        ['I’d like to deposit this check, please. — Quisiera depositar este cheque, por favor.', 'I withdrew two hundred dollars from the ATM. — Retiré doscientos dólares del cajero.', 'Could you tell me my account balance? — ¿Me podría decir el saldo de mi cuenta?'],
        [['I’d like to ___ \$100 from my account.', 'withdraw', 'deposit', 'earn', 'owe', 'Withdraw significa retirar dinero de la cuenta.'], ['The amount of money in your account is your ___.', 'balance', 'overdraft', 'interest', 'dividend', 'Balance es el saldo disponible.']]),
      CapituloExtra('Deudas y préstamos', 'Aprender a hablar de deudas, créditos y pagos a plazos.', 'Para hablar de dinero prestado usa “borrow from” (recibir) y “lend to” (dar): “I borrowed money from the bank”. Con deudas usa “owe”: “I owe the bank \$5,000”.',
        [['debt', 'deuda'], ['loan', 'préstamo'], ['mortgage', 'hipoteca'], ['borrow', 'pedir prestado'], ['lend', 'prestar'], ['down payment', 'enganche'], ['credit score', 'historial crediticio'], ['installment', 'mensualidad, pago a plazos']],
        ['I borrowed money from the bank to buy a car. — Pedí dinero prestado al banco para comprar un auto.', 'They made a down payment of twenty percent. — Dieron un enganche de veinte por ciento.', 'A good credit score helps you get a lower interest rate. — Un buen historial crediticio te ayuda a obtener una tasa más baja.'],
        [['I need to ___ some money from the bank to buy a house.', 'borrow', 'lend', 'deposit', 'withdraw', 'Borrow es pedir prestado.'], ['The bank will ___ me \$10,000 for my business.', 'lend', 'borrow', 'owe', 'earn', 'El banco presta (lend) dinero a la persona.']]),
      CapituloExtra('Impuestos y seguros', 'Aprender a entender impuestos, seguros y reembolsos.', 'Para hablar de obligaciones usa “have to” y “must”: “You have to file your taxes every year”. Con los seguros se dice “pay a premium” y “be covered”.',
        [['tax', 'impuesto'], ['insurance', 'seguro'], ['refund', 'devolución'], ['deduction', 'deducción'], ['premium', 'prima del seguro'], ['coverage', 'cobertura'], ['deductible', 'deducible'], ['file taxes', 'presentar la declaración de impuestos']],
        ['You have to file your taxes before April. — Tienes que presentar tu declaración de impuestos antes de abril.', 'My insurance covers car accidents. — Mi seguro cubre accidentes de auto.', 'I’m expecting a tax refund this year. — Espero una devolución de impuestos este año.'],
        [['I pay a monthly ___ for my health insurance.', 'premium', 'refund', 'deduction', 'mortgage', 'Premium es lo que pagas periódicamente por el seguro.'], ['We ___ file our taxes before the deadline.', 'have to', 'has to', 'having to', 'must to', '“Have to” expresa obligación con el sujeto we.']]),
      CapituloExtra('Decisiones financieras', 'Aprender a evaluar compras y decisiones de dinero con condicionales.', 'Para hablar de situaciones hipotéticas usa el segundo condicional: “If I earned more, I would save more”. Para decir que puedes pagar algo usa “can afford”: “I can’t afford a new car”.',
        [['afford', 'poder pagar'], ['worth', 'valer la pena'], ['cut back', 'reducir gastos'], ['spend', 'gastar'], ['waste', 'desperdiciar'], ['profit', 'ganancia'], ['wealth', 'riqueza'], ['save up', 'juntar dinero']],
        ['If I earned more, I would save more. — Si ganara más, ahorraría más.', 'I can’t afford a new laptop right now. — No puedo pagar una laptop nueva ahorita.', 'It’s worth paying more for good quality. — Vale la pena pagar más por buena calidad.'],
        [['If I had more money, I ___ buy a house.', 'would', 'will', 'am', 'had', 'El segundo condicional usa “would” en el resultado.'], ['I can’t ___ a vacation this year because it’s too expensive.', 'afford', 'waste', 'profit', 'worth', '“Can’t afford” significa no poder pagar algo.']]),
    ]),
    UnidadExtra(39, 'Ciencia y tecnología avanzada', true, [
      CapituloExtra('Inteligencia artificial', 'Aprender a explicar qué es la IA y cómo se usa.', 'Para definir conceptos usa “X is a system that + verbo”: “A chatbot is a program that answers questions”. Para hablar de capacidades usa “can” y “be able to”.',
        [['artificial intelligence', 'inteligencia artificial'], ['machine learning', 'aprendizaje automático'], ['algorithm', 'algoritmo'], ['chatbot', 'chatbot'], ['bias', 'sesgo'], ['neural network', 'red neuronal'], ['automation', 'automatización'], ['prompt', 'instrucción al modelo']],
        ['A chatbot is a program that answers questions. — Un chatbot es un programa que responde preguntas.', 'Machine learning allows computers to learn from examples. — El aprendizaje automático permite que las computadoras aprendan de ejemplos.', 'An algorithm can show bias if the data is unfair. — Un algoritmo puede mostrar sesgo si los datos son injustos.'],
        [['A chatbot is a program ___ answers questions automatically.', 'that', 'what', 'who', 'where', 'Para cosas se usa el pronombre relativo “that”.'], ['What does “bias” mean in AI?', 'An unfair tendency in results', 'A faster processor', 'A kind of battery', 'A secure password', 'Bias es un sesgo o tendencia injusta en los resultados.']]),
      CapituloExtra('Datos y análisis', 'Aprender a hablar de datos, almacenamiento y análisis.', 'Para describir tendencias usa “increase”, “decrease” y “remain stable”: “Data usage has increased sharply”. “Data” suele usarse como incontable: “The data is clear”.',
        [['dataset', 'conjunto de datos'], ['analyze', 'analizar'], ['database', 'base de datos'], ['cloud', 'la nube'], ['trend', 'tendencia'], ['insight', 'hallazgo útil'], ['storage', 'almacenamiento'], ['privacy', 'privacidad']],
        ['We analyze the dataset to find trends. — Analizamos el conjunto de datos para encontrar tendencias.', 'Our files are saved in the cloud. — Nuestros archivos están guardados en la nube.', 'Companies must protect users’ privacy. — Las empresas deben proteger la privacidad de los usuarios.'],
        [['Data usage has ___ sharply in the last five years.', 'increased', 'increase', 'increasing', 'to increase', 'Con “has” se usa el participio: increased.'], ['Where do many companies store files online instead of on their own computers?', 'in the cloud', 'in the trend', 'in the insight', 'in the privacy', 'Los archivos en línea se guardan en la nube (the cloud).']]),
      CapituloExtra('Innovación e inventos', 'Aprender a describir inventos, ideas nuevas y emprendimientos.', 'Para hablar de inventos usa el pasado simple y el pasivo: “The telephone was invented in 1876”. Para predecir usa “will”: “This device will change how we work”.',
        [['innovation', 'innovación'], ['prototype', 'prototipo'], ['startup', 'empresa emergente'], ['breakthrough', 'gran avance'], ['invent', 'inventar'], ['patent', 'patente'], ['disruptive', 'disruptivo'], ['research', 'investigación']],
        ['The telephone was invented in 1876. — El teléfono fue inventado en 1876.', 'The startup built a prototype in six months. — La empresa emergente construyó un prototipo en seis meses.', 'This breakthrough will change medicine. — Este gran avance cambiará la medicina.'],
        [['The light bulb ___ by Thomas Edison.', 'was invented', 'invented', 'is inventing', 'has invent', 'La voz pasiva en pasado es “was invented”.'], ['A first working model of a new product is called a ___.', 'prototype', 'patent', 'dataset', 'startup', 'Prototype es el primer modelo funcional de un producto.']]),
      CapituloExtra('Ciberseguridad', 'Aprender a hablar de amenazas digitales y cómo protegerse.', 'Para dar consejos usa “should”, “shouldn’t” y el imperativo: “Don’t click on suspicious links”. Para hablar de causas usa “because” y “so”.',
        [['password', 'contraseña'], ['hacker', 'hacker'], ['phishing', 'suplantación por correo'], ['malware', 'software malicioso'], ['encryption', 'cifrado'], ['firewall', 'cortafuegos'], ['breach', 'filtración de datos'], ['authentication', 'autenticación']],
        ['You should use a strong password. — Deberías usar una contraseña segura.', 'Don’t click on links from unknown senders. — No hagas clic en enlaces de remitentes desconocidos.', 'A data breach exposed millions of accounts. — Una filtración de datos expuso millones de cuentas.'],
        [['You ___ share your password with anyone.', 'shouldn’t', 'should', 'must to', 'can to', 'Para aconsejar no hacerlo se usa “shouldn’t”.'], ['An email that tricks you into giving personal information is called ___.', 'phishing', 'encryption', 'a firewall', 'authentication', 'Phishing es el engaño por correo para robar datos.']]),
      CapituloExtra('Energía y sostenibilidad', 'Aprender a hablar de fuentes de energía y medio ambiente.', 'Para comparar fuentes usa comparativos: “Solar energy is cleaner than coal”. Para hablar de causas y efectos usa “lead to” y “result in”.',
        [['renewable', 'renovable'], ['solar panel', 'panel solar'], ['wind turbine', 'aerogenerador'], ['battery', 'batería'], ['grid', 'red eléctrica'], ['fossil fuel', 'combustible fósil'], ['emissions', 'emisiones'], ['sustainable', 'sostenible']],
        ['Solar energy is cleaner than coal. — La energía solar es más limpia que el carbón.', 'Burning fossil fuels leads to higher emissions. — Quemar combustibles fósiles provoca más emisiones.', 'Wind turbines produce renewable electricity. — Los aerogeneradores producen electricidad renovable.'],
        [['Solar power is ___ than coal.', 'cleaner', 'more clean', 'cleanest', 'clean as', 'Los adjetivos cortos forman el comparativo con -er: cleaner.'], ['Energy sources like sun and wind are called ___ energy.', 'renewable', 'fossil', 'disruptive', 'stored', 'Las fuentes que no se agotan son energía renovable.']]),
      CapituloExtra('Salud digital', 'Aprender a hablar de tecnología aplicada a la salud.', 'Para explicar utilidad usa “be used to + verbo” o “help + verbo”: “Wearables help people monitor their heart rate”. Para recomendaciones médicas usa “should” y “need to”.',
        [['telemedicine', 'telemedicina'], ['wearable', 'dispositivo ponible'], ['health record', 'expediente médico'], ['monitor', 'monitorear'], ['diagnosis', 'diagnóstico'], ['symptom', 'síntoma'], ['prescription', 'receta médica'], ['fitness tracker', 'pulsera de actividad']],
        ['Telemedicine lets patients see a doctor online. — La telemedicina permite que los pacientes vean a un médico en línea.', 'A fitness tracker can monitor your heart rate. — Una pulsera de actividad puede monitorear tu ritmo cardiaco.', 'The doctor gave me a prescription. — El médico me dio una receta.'],
        [['Wearable devices help people ___ their heart rate.', 'monitor', 'monitors', 'monitoring', 'to monitoring', 'Después de “help” se usa el verbo en forma base.'], ['A doctor’s identification of an illness is called a ___.', 'diagnosis', 'prescription', 'wearable', 'symptom', 'Diagnosis es la identificación de la enfermedad.']]),
    ]),
    UnidadExtra(40, 'Preparación para exámenes de inglés', true, [
      CapituloExtra('Conocer los exámenes', 'Aprender a distinguir los exámenes internacionales y su vocabulario básico.', 'TOEFL e IELTS evalúan cuatro habilidades: reading, listening, speaking y writing. Cambridge usa niveles como B1 y B2. Para hablar de metas usa “I need a score of…”: “I need a score of 6.5 to apply”.',
        [['exam', 'examen'], ['score', 'puntaje'], ['band', 'nivel de puntaje del IELTS'], ['section', 'sección'], ['level', 'nivel'], ['certificate', 'certificado'], ['requirement', 'requisito'], ['registration', 'inscripción']],
        ['I need a score of 6.5 on the IELTS. — Necesito un puntaje de 6.5 en el IELTS.', 'The exam has four sections. — El examen tiene cuatro secciones.', 'This certificate is accepted by many universities. — Este certificado es aceptado por muchas universidades.'],
        [['I need a ___ of 80 on the TOEFL to enter this university.', 'score', 'section', 'registration', 'certificate of', 'Score es el puntaje obtenido en el examen.'], ['The exam has four ___: reading, listening, speaking and writing.', 'sections', 'bands', 'levels of', 'requirement', 'Las partes del examen se llaman sections.']]),
      CapituloExtra('Estrategias de reading', 'Aprender técnicas para leer textos rápido y responder mejor.', 'Antes de contestar haz un “skim” del texto para captar la idea general y un “scan” para buscar datos concretos. Para vocabulario nuevo usa el contexto: “From the context, I think ‘reluctant’ means unwilling”.',
        [['skim', 'leer por encima'], ['scan', 'buscar datos específicos'], ['main idea', 'idea principal'], ['detail', 'detalle'], ['inference', 'inferencia'], ['paragraph', 'párrafo'], ['passage', 'texto, pasaje'], ['context', 'contexto']],
        ['First, skim the passage to find the main idea. — Primero lee por encima el texto para encontrar la idea principal.', 'Scan the paragraph for names and dates. — Busca nombres y fechas en el párrafo.', 'An inference is not stated directly in the text. — Una inferencia no está dicha directamente en el texto.'],
        [['To find a date quickly in a text, you should ___ it.', 'scan', 'skim', 'paraphrase', 'rehearse', 'Scan es buscar un dato concreto rápidamente.'], ['What is the “main idea” of a passage?', 'The central point of the text', 'A small detail', 'A difficult word', 'The last sentence only', 'La idea principal es el punto central del texto.']]),
      CapituloExtra('Estrategias de listening', 'Aprender a mejorar la comprensión auditiva durante el examen.', 'Lee las preguntas antes de escuchar y subraya palabras clave. Anota con abreviaturas: “Take notes while you listen”. Cuidado con los distractores: el hablante puede cambiar de opinión.',
        [['lecture', 'clase magistral'], ['take notes', 'tomar apuntes'], ['keyword', 'palabra clave'], ['accent', 'acento'], ['speaker', 'hablante'], ['tone', 'tono'], ['distractor', 'opción engañosa'], ['recording', 'grabación']],
        ['Read the questions before you listen to the recording. — Lee las preguntas antes de escuchar la grabación.', 'The speaker has a British accent. — El hablante tiene acento británico.', 'Take notes during the lecture. — Toma apuntes durante la clase.'],
        [['In the lecture, you should ___ notes about important ideas.', 'take', 'do', 'put', 'hold', 'La colocación correcta es “take notes”.'], ['A wrong answer that sounds similar to something in the recording is a ___.', 'distractor', 'keyword', 'lecture', 'tone', 'Un distractor es una opción incorrecta que parece correcta.']]),
      CapituloExtra('Estrategias de speaking', 'Aprender a hablar con fluidez y organizar tus ideas en la parte oral.', 'Da tu opinión con “In my opinion…” o “I strongly believe that…” y apóyala con “For example…”. Si dudas, usa muletillas útiles: “Let me think”. Evita quedarte en silencio.',
        [['fluency', 'fluidez'], ['pronunciation', 'pronunciación'], ['pause', 'pausa'], ['opinion', 'opinión'], ['describe', 'describir'], ['hesitate', 'titubear'], ['cue card', 'tarjeta con tema'], ['rehearse', 'ensayar']],
        ['In my opinion, online classes are very useful. — En mi opinión, las clases en línea son muy útiles.', 'Don’t hesitate for too long before you answer. — No titubees demasiado antes de responder.', 'I rehearse with a timer every day. — Ensayo con un cronómetro todos los días.'],
        [['___ my opinion, learning English is worth the effort.', 'In', 'On', 'At', 'By', 'La expresión correcta es “In my opinion”.'], ['Speaking smoothly and without many stops is called ___.', 'fluency', 'pronunciation', 'hesitation', 'a pause', 'Fluency es la fluidez al hablar.']]),
      CapituloExtra('Estrategias de writing', 'Aprender a estructurar un ensayo claro y bien conectado.', 'Un buen ensayo tiene introducción, desarrollo y conclusión. Usa conectores como “however”, “moreover” y “as a result”: “Cars are convenient; however, they pollute the air”. Revisa al final.',
        [['essay', 'ensayo'], ['thesis', 'tesis'], ['topic sentence', 'oración temática'], ['conclusion', 'conclusión'], ['linking word', 'conector'], ['paraphrase', 'parafrasear'], ['outline', 'esquema'], ['proofread', 'revisar el texto']],
        ['Write an outline before you start the essay. — Escribe un esquema antes de comenzar el ensayo.', 'Cars are convenient; however, they pollute the air. — Los autos son cómodos; sin embargo, contaminan el aire.', 'Always proofread your essay at the end. — Siempre revisa tu ensayo al final.'],
        [['Cars are fast; ___, they pollute the air.', 'however', 'because', 'moreover of', 'so that', '“However” introduce un contraste con punto y coma antes.'], ['The first sentence of a body paragraph that presents its main point is the ___.', 'topic sentence', 'outline', 'thesis of', 'paraphrase', 'La oración temática presenta la idea principal del párrafo.']]),
      CapituloExtra('Errores comunes y simulacro', 'Aprender a evitar errores frecuentes y practicar con un examen de práctica.', 'Errores típicos: olvidar la -s de he/she/it (“She works”), usar mal los artículos y confundir preposiciones. Haz un simulacro con tiempo real: “I take a mock test every weekend”, y revisa tus fallos.',
        [['mistake', 'error'], ['mock test', 'examen de práctica'], ['timer', 'cronómetro'], ['answer sheet', 'hoja de respuestas'], ['guess', 'adivinar'], ['strategy', 'estrategia'], ['weakness', 'punto débil'], ['improve', 'mejorar']],
        ['I take a mock test every weekend. — Hago un examen de práctica cada fin de semana.', 'Use a timer to practice time management. — Usa un cronómetro para practicar el manejo del tiempo.', 'Review your mistakes to improve. — Revisa tus errores para mejorar.'],
        [['She ___ in a bank, but her brother works in a school.', 'works', 'work', 'working', 'to work', 'Con she el presente simple lleva -s: works.'], ['Taking a ___ test helps you practice under real exam conditions.', 'mock', 'guess', 'weak', 'timer', 'Mock test es un examen de práctica que simula el real.']]),
    ]),
  ];
}
